  .tob-info { position: absolute; inset: 0; z-index: 5; overflow-y: auto; display: none; padding: 12px 20px 40px var(--tob-left); -webkit-overflow-scrolling: touch; }
  .tob-info p { margin: 0; max-width: 780px; font: 400 19px/30px var(--tob-sans); }
  .tob-info sup { font-size: 58%; font-family: var(--tob-mono); vertical-align: baseline; position: relative; top: -.9em; padding-left: 2px; }  /* footnote numbers */
  .tob-info sup.ch { font-size: 80%; font-family: inherit; top: -.5em; padding-left: 0; }  /* ion charges */
  .tob-info-open .tob-info { display: block; }
  .tob-dim { transition: opacity .3s, filter .3s; }
