  * { box-sizing: border-box; }
  html { -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }
  html, body { margin: 0; background: var(--tob-stage); }
  body { color: #fff; font-family: var(--tob-mono); letter-spacing: .6px; -webkit-font-smoothing: antialiased; hyphens: none; }
  button {
    font: inherit; letter-spacing: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; text-align: left;
    touch-action: manipulation; -webkit-tap-highlight-color: transparent;
  }
  button:focus-visible { outline: 2px solid var(--tob-highlight); outline-offset: 2px; }
  ol, ul { list-style: none; margin: 0; padding: 0; }

  /* two columns: [ animation + legend ] [ steps ] */
  .tob { display: grid; grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr); }

  /* ---------- column 1: stage ---------- */
  .tob-stage { background: var(--tob-stage); border-right: 1px solid #fff; min-width: 0; display: flex; flex-direction: column; }
  .tob-head { padding: 22px var(--tob-left) 14px; display: flex; flex-direction: column; align-items: flex-start; gap: 14px; }
  .tob-title { margin: 0; font: 700 19px/30px var(--tob-sans); }
  .tob-icon {
    position: relative; display: grid; place-items: center; border-radius: 50%;
    background: #fff; border: 1px solid #222; flex: none;
    transition: background-color .15s, transform .3s;
  }
  .tob-icon::after { content: ""; position: absolute; inset: -8px; }   /* larger touch target */
  .tob-icon svg { width: 100%; height: 100%; fill: #000; transition: fill .15s; }
  .tob-tools { display: flex; gap: 14px; align-items: center; }
  /* condition switch (e.g. Dark / Light), shown only by widgets that have more than one animation */
  .tob-seg { display: flex; border: 1px solid rgba(255, 255, 255, .55); border-radius: 17px; overflow: hidden; margin-right: 6px; }
  .tob-seg[hidden] { display: none; }
  .tob-seg button { min-height: 32px; padding: 0 16px; font: 700 14px/1 var(--tob-sans); text-align: center; transition: background-color .15s, color .15s; }
  .tob-seg button[aria-pressed="true"] { background: #fff; color: #222; }
  .tob-anim { width: 100%; height: 100%; }
  .tob-anim[hidden] { display: none; }
  .tob-info-btn, .tob-narr-btn { width: 32px; height: 32px; }   /* whole pixels, so the drawing below starts on a pixel boundary */
  .tob-narr-btn .ln { fill: none; stroke: #000; stroke-width: 1.3; stroke-linecap: round; transition: stroke .15s; }
  .tob-narr-btn .off { stroke: #000; stroke-width: 1.3; stroke-linecap: round; }
  .tob-narr-btn[aria-pressed="true"] { background: var(--tob-accent); border-color: #fff; }
  .tob-narr-btn[aria-pressed="true"] svg { fill: var(--ob-on-accent, #fff); }
  .tob-narr-btn[aria-pressed="true"] .ln { stroke: var(--ob-on-accent, #fff); }
  .tob-narr-btn[aria-pressed="true"] .off, .tob-narr-btn[aria-pressed="false"] .ln { display: none; }
  .tob-narr-btn.is-speaking { animation: tob-pulse 1.2s ease-in-out infinite; }
  @keyframes tob-pulse { 50% { box-shadow: 0 0 0 5px rgba(204, 1, 190, .35); } }
  .tob-info-open .tob-info-btn { transform: rotate(45deg); }
  .tob-body { position: relative; flex: 1; display: flex; flex-direction: column; }
  .tob-caption {
    background: var(--tob-accent);
    display: flex; justify-content: space-between; align-items: flex-start; gap: 16px;
    padding: 10px 15px 10px var(--tob-left);
    font: 400 19px/30px var(--tob-sans);
    color: var(--ob-on-accent, #fff);
  }
  .tob-caption-text { padding: 5px 0 5px 2.5px; max-width: 780px; min-height: 40px; }
  .tob-nav { display: flex; align-items: center; gap: 10px; flex: none; }
  .tob-count { font: 400 13px/1 var(--tob-mono); white-space: nowrap; padding-right: 4px; opacity: .9; }
  .tob-ctl { width: 40px; height: 40px; }
  .tob-next svg { transform: rotate(-90deg); }
  .tob-prev svg { transform: rotate(90deg); }
  .tob-pause .i-play, .tob-pause[aria-pressed="true"] .i-pause { display: none; }
  .tob-pause[aria-pressed="true"] .i-play { display: inline; }
  /* the animation: as wide as the column, but never so tall that caption + animation + legend leave the frame */
  .tob-canvas { width: 100%; padding: 14px 20px 10px var(--tob-left); height: 420px; /* refined by applyFraming() */ }
  .tob-canvas svg { display: block; width: 100%; height: 100%; }

  /* legend: directly under the animation it controls */
  .tob-legend { border-top: 1px solid var(--tob-line); padding: 12px 20px 16px var(--tob-left); font: 700 13px/16px var(--tob-mono); }
  .tob-legend ul { display: flex; flex-wrap: wrap; gap: 8px; }
  /* each entry is drawn as a button so it reads as something to press */
  .tob-chip {
    display: flex; align-items: center; gap: 10px; min-height: 44px; padding: 6px 14px 6px 10px;
    border: 1px solid rgba(255, 255, 255, .38); border-radius: 22px; background: rgba(255, 255, 255, .05);
    transition: color .15s, background-color .15s, border-color .15s, opacity .2s;
  }
  .tob-chip[aria-pressed="true"] { color: var(--tob-highlight); border-color: var(--tob-highlight); background: rgba(0, 0, 0, .3); }
  .tob-chip.is-absent { opacity: .38; border-style: dashed; }   /* not in the picture during this step */
  .tob-chip[aria-pressed="true"] .tob-chip-label { text-decoration: underline; text-underline-offset: 3px; }
  .tob-chip svg { width: 25px; height: 25px; flex: none; fill: #fff; color: #fff; }
  .tob-chip sup { position: relative; top: -.5em; font-size: 80%; vertical-align: baseline; }

  /* Highlight outline (see "highlight outline" in the script): drawn in an overlay SVG on its own layer. */
  .tob-canvas { position: relative; }
  /* name tag that travels with a molecule whose identity changes along the way (see cfg.followLabel) */
  .tob-follow {
    position: absolute; left: 0; top: 0; z-index: 2; pointer-events: none; white-space: nowrap; will-change: transform;
    font: 700 12px/1 var(--tob-mono); color: #fff; background: rgba(0, 0, 0, .78); padding: 5px 8px; border-radius: 4px;
  }
  .tob-follow[hidden] { display: none; }
  .tob-overlay { position: absolute; z-index: 1; pointer-events: none; will-change: transform; overflow: visible; }
  .tob-halo path {
    fill: none !important;
    stroke: var(--tob-highlight) !important; stroke-opacity: 1 !important;
    stroke-width: 6px !important; stroke-linejoin: round; stroke-linecap: round;   /* the outer half is what shows */
    vector-effect: non-scaling-stroke;   /* same thickness on screen at every size */
  }
