  @media (hover: hover) {
    .tob-ctl:hover { background: #222; border-color: #fff; }
    .tob-ctl:hover svg { fill: #fff; }
    .tob-chip:hover { border-color: var(--tob-highlight); }
    .tob-seg button[aria-pressed="false"]:hover { background: rgba(255, 255, 255, .16); }
    .tob-step:hover { color: var(--tob-accent); }
    .tob-chip:hover { color: var(--tob-highlight); }
  }
  .tob-ctl:active { background: #222; border-color: #fff; }
  .tob-ctl:active svg { fill: #fff; }
  .tob-step:active { color: var(--tob-accent); }

  /* touch screens: finger-sized arrow */
  @media (pointer: coarse) { .tob-ctl { width: 44px; height: 44px; } .tob-seg { border-radius: 22px; } .tob-seg button { min-height: 44px; padding: 0 18px; } }

  /* ---------- tablets / small laptops ---------- */
  @media (max-width: 1100px) {
    :root { --tob-left: 24px; }
    .tob { grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr); }
    .tob-head { padding-top: 16px; gap: 10px; }
    .tob-caption { font-size: 17px; line-height: 26px; }
    .tob-info p { font-size: 17px; line-height: 27px; }
    .tob-steps { font-size: 14px; line-height: 21px; padding-top: 16px; }
    .tob-step { padding: 8px 20px 12px 14px; }
  }

  /* ---------- phones: one column; steps follow the animation and legend ---------- */
  @media (max-width: 700px) {
    :root { --tob-left: 16px; }
    .tob-halo path { stroke-width: 4px !important; }
    .tob { display: block; }
    .tob-stage { border-right: 0; }
    .tob-head { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: space-between; padding: 12px var(--tob-left); }
    .tob-canvas { padding: 12px var(--tob-left) 8px; }
    .tob-caption { flex-wrap: wrap; gap: 8px 16px; padding-right: var(--tob-left); }
    .tob-caption-text { flex: 1 1 100%; min-height: 0; padding: 2px 0 0; }
    .tob-nav { flex: 1 1 100%; justify-content: flex-end; }
    .tob-count { display: none; }   /* the numbered buttons show the position */
    .tob-dots { display: flex; gap: 4px; padding: 10px var(--tob-left) 2px; }
    .tob-steps { display: none; }
    .tob-legend { padding: 10px var(--tob-left) 14px; }
    .tob-legend ul { gap: 6px; }
    .tob-chip { padding: 6px 12px 6px 8px; gap: 8px; }
    .tob-chip svg { width: 22px; height: 22px; }
    .tob-info { position: static; padding: 14px var(--tob-left) 24px; overflow: visible; }
    .tob-info-open .tob-caption, .tob-info-open .tob-dots, .tob-info-open .tob-canvas, .tob-info-open .tob-legend { display: none; }
  }
  @media (prefers-reduced-motion: reduce) {
    .tob-icon, .tob-dim, .tob-step, .tob-chip, .tob-dot, .tob-seg button { transition: none; }
    .tob-narr-btn.is-speaking { animation: none; }
  }

  /* =====================================================================================================
     "Site" theme (class "tob-site" on <html>): the look of the original site's in-page animations, for widgets
     that take half a page. Light grey page background, black text and icons, teal for whatever is active, the
     caption in a white box with a teal border. One column, no step list, the animation as large as it will go.
     ===================================================================================================== */
  html.tob-site {
    --tob-stage: #F3F4F6;      /* the site's page background */
    --tob-accent: var(--ob-accent, #00D9B8);     /* primaryMed; the chapter colour inside the book */
    --tob-highlight: var(--ob-accent, #00D9B8);
    --tob-line: rgba(0, 0, 0, .25);
    --tob-left: 20px;
  }
  html.tob-site body { color: #000; }
  html.tob-site button:focus-visible { outline-color: #000; }
  html.tob-site .tob { display: block; }
  html.tob-site .tob-stage { border-right: 0; }
  html.tob-site .tob-steps, html.tob-site .tob-dots { display: none; }
  html.tob-site .tob-head { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px 16px; padding: 14px var(--tob-left) 10px; }
  /* Dark / Light: rectangular blocks, the active one filled teal, as on the site */
  html.tob-site .tob-seg { border: 0; border-radius: 0; overflow: visible; gap: 8px; margin-right: 8px; }
  html.tob-site .tob-seg button { border: 1px solid #000; min-width: 86px; min-height: 32px; padding: 0 14px; font: 400 12px/1 var(--tob-mono); letter-spacing: .6px; }
  html.tob-site .tob-seg button[aria-pressed="true"] { background: var(--tob-highlight); border-color: var(--tob-highlight); color: #000; font-weight: 600; }
  html.tob-site .tob-narr-btn[aria-pressed="true"] { background: var(--tob-highlight); border-color: #000; }
  html.tob-site .tob-narr-btn[aria-pressed="true"] svg { fill: #000; }
  html.tob-site .tob-narr-btn[aria-pressed="true"] .ln { stroke: #000; }
  html.tob-site .tob-narr-btn.is-speaking { animation-name: tob-pulse-site; }
  @keyframes tob-pulse-site { 50% { box-shadow: 0 0 0 5px rgba(0, 217, 184, .55); } }
  /* caption: the site's caption box, white with a teal border */
  html.tob-site .tob-caption {
    margin: 0 var(--tob-left); padding: 8px 8px 8px 14px; align-items: center; gap: 12px;
    background: #fff; color: #000; border: 1px solid var(--tob-highlight); font: 400 13px/19px var(--tob-mono);
  }
  html.tob-site .tob-caption-text { padding: 0; max-width: none; flex: 1 1 auto; }
  html.tob-site .tob-nav { gap: 8px; }
  html.tob-site .tob-count {
    display: block; padding: 6px 9px; border: 1.5px solid var(--tob-highlight); border-radius: 14px; opacity: 1;
    color: #007F6C; font: 600 13px/1 var(--tob-sans); letter-spacing: 0;
  }
  html.tob-site .tob-ctl { width: 34px; height: 34px; }
  html.tob-site .tob-ctl:active { background: var(--tob-highlight); border-color: #000; }
  html.tob-site .tob-ctl:active svg { fill: #000; }
  html.tob-site .tob-canvas { padding: 8px var(--tob-left) 4px; }
  /* legend: black icons and labels, as in the site's legend */
  html.tob-site .tob-legend { border-top: 0; padding: 4px var(--tob-left) 14px; font: 400 12px/16px var(--tob-mono); }
  html.tob-site .tob-legend ul { gap: 6px; }
  html.tob-site .tob-chip { border: 1px solid rgba(0, 0, 0, .55); border-radius: 0; background: transparent; min-height: 36px; padding: 4px 12px 4px 8px; gap: 8px; }
  html.tob-site .tob-chip svg { width: 22px; height: 22px; fill: #000; color: #000; }
  html.tob-site .tob-chip[aria-pressed="true"] { color: #000; border-color: var(--tob-highlight); background: var(--tob-highlight); font-weight: 600; }
  html.tob-site .tob-chip[aria-pressed="true"] .tob-chip-label { text-decoration: none; }
  @media (hover: hover) {
    html.tob-site .tob-ctl:hover { background: var(--tob-highlight); border-color: #000; }
    html.tob-site .tob-ctl:hover svg { fill: #000; }
    html.tob-site .tob-chip:hover { color: #000; border-color: var(--tob-highlight); }
    html.tob-site .tob-seg button[aria-pressed="false"]:hover { background: transparent; border-color: var(--tob-highlight); }
  }
  @media (pointer: coarse) {
    html.tob-site .tob-ctl { width: 44px; height: 44px; }
    html.tob-site .tob-seg button, html.tob-site .tob-chip { min-height: 44px; }
  }
  @media (max-width: 700px) {
    html.tob-site { --tob-left: 14px; }
    html.tob-site .tob-caption { flex-wrap: wrap; gap: 8px 12px; padding: 10px 10px 8px 12px; font-size: 14px; line-height: 20px; }
    html.tob-site .tob-caption-text { flex: 1 1 100%; }
    html.tob-site .tob-nav { flex: 1 1 100%; justify-content: flex-end; }
    html.tob-site .tob-count { margin-right: auto; }
  }

  /* ---------- "hold" widgets (cfg.hold): each step is a still picture, with a switch to a second version of it ---------- */
  .tob-hold .tob-pause { display: none; }
  /* the steps are alternatives, not a sequence: names instead of numbers */
  .tob-hold .tob-step-num, .tob-hold .tob-count { display: none; }
  .tob-hold .tob-dots { flex-wrap: wrap; gap: 6px; }
  .tob-hold .tob-dot { flex: 1 1 auto; width: auto; padding: 0 10px; font: 700 12px/1 var(--tob-sans); letter-spacing: 0; white-space: nowrap; }
  .tob-seg button:disabled { opacity: .4; cursor: default; }

  /* =====================================================================================================
     "Choices" layout (cfg.layout === "choices", class "tob-choices" on <html>): the site's own look for
     Refraction errors. Grey-green page, black text; title, "+" and a block of state buttons on the left (each
     refractive error with a "Corrected" button beside it), the drawing on the right. The explanation opens over
     a dark page, as on the site.
     ===================================================================================================== */
  html.tob-choices { --tob-stage: #8F9E9D; --tob-accent: var(--ob-accent, #00D9B8); --tob-highlight: var(--ob-accent, #00D9B8); --tob-left: 28px; }
  html.tob-choices, html.tob-choices body, html.tob-choices .tob-stage { transition: background-color .3s, color .3s; }
  html.tob-choices body { color: #000; }
  html.tob-choices.tob-dark, html.tob-choices.tob-dark body, html.tob-choices.tob-dark .tob-stage { background: #333; color: #fff; }
  html.tob-choices button:focus-visible { outline-color: #000; }
  html.tob-choices .tob { display: block; }
  html.tob-choices .tob-steps, html.tob-choices .tob-dots, html.tob-choices .tob-seg, html.tob-choices .tob-nav { display: none !important; }
  html.tob-choices .tob-stage {
    position: relative; border-right: 0; display: grid; align-content: start;
    grid-template-columns: minmax(calc(222px + var(--tob-left) + 28px), 1fr) minmax(0, 2fr); padding-bottom: 24px;
    grid-template-rows: auto auto auto 1fr;
  }
  html.tob-choices .tob-body { display: contents; }
  html.tob-choices .tob-head { grid-column: 1; grid-row: 1; padding: 25px 0 16px var(--tob-left); gap: 20px; }
  html.tob-choices .tob-pick { grid-column: 1; grid-row: 2; padding-left: var(--tob-left); width: calc(222px + var(--tob-left)); display: grid; gap: 10px; }
  html.tob-choices .tob-pick-row { display: grid; grid-template-columns: 1fr 1fr; }
  html.tob-choices .tob-pick button {
    min-height: 48px; padding: 6px 8px; border: 1px solid #000; color: #333; text-align: center;
    font: 400 12px/16px var(--tob-mono); letter-spacing: 0; transition: background-color .1s, color .1s, border-color .1s;
  }
  html.tob-choices .tob-pick .is-wide { grid-column: 1 / -1; }
  html.tob-choices .tob-pick .tob-pick-alt { background: #fff; border-left: 0; }
  html.tob-choices .tob-pick button.is-on { background: var(--tob-highlight); color: #000; }
  html.tob-choices .tob-pick button.is-row { color: #000; border-color: var(--tob-highlight); border-right-color: #000; }   /* its "Corrected" is on */
  html.tob-choices .tob-caption {
    grid-column: 1; grid-row: 3; background: none; display: block; margin: 0;
    padding: 18px 0 20px var(--tob-left); width: calc(222px + var(--tob-left)); font: 400 13px/19px var(--tob-mono);
  }
  html.tob-choices .tob-caption-text { padding: 0; min-height: 0; max-width: none; }
  /* on the site the drawing sits in the right two-thirds of the page, 900px wide at most */
  html.tob-choices .tob-view { grid-column: 2; grid-row: 1 / span 4; align-self: center; justify-self: center; min-width: 0; width: 100%; max-width: 928px; }
  html.tob-choices .tob-canvas { padding: 20px 28px 20px 0; background: none !important; }
  html.tob-choices .tob-legend { display: none; }
  /* the explanation is laid over the buttons and drawing but stays in the page flow, so the widget grows to fit
     the whole text and nothing has to be scrolled */
  html.tob-choices .tob-info {
    position: relative; inset: auto; overflow: visible; grid-column: 1 / -1; grid-row: 2 / span 3; align-self: start;
    padding: 24px 28px 30px var(--tob-left); color: #fff;
  }
  html.tob-choices .tob-info p { max-width: 700px; }
  html.tob-choices .tob-info-open .tob-dim { opacity: .15; }
  html.tob-choices .tob-narr-btn[aria-pressed="true"] { background: var(--tob-highlight); border-color: #000; }
  html.tob-choices .tob-narr-btn[aria-pressed="true"] svg { fill: #000; }
  html.tob-choices .tob-narr-btn[aria-pressed="true"] .ln { stroke: #000; }
  html.tob-choices .tob-narr-btn.is-speaking { animation-name: tob-pulse-site; }
  @media (hover: hover) {
    html.tob-choices .tob-pick button:not(.is-on):hover { color: var(--tob-highlight); border-color: var(--tob-highlight); }
    html.tob-choices .tob-icon:hover { background: var(--tob-highlight); }
  }
  @media (max-width: 700px) {
    html.tob-choices { --tob-left: 16px; }
    html.tob-choices .tob-stage { display: block; }
    html.tob-choices .tob-head { flex-direction: column; align-items: flex-start; padding: 16px var(--tob-left) 12px; gap: 12px; }
    html.tob-choices .tob-pick { width: auto; max-width: 340px; padding-right: var(--tob-left); }
    html.tob-choices .tob-caption { width: auto; padding: 14px var(--tob-left) 4px; font-size: 14px; line-height: 20px; }
    html.tob-choices .tob-canvas { padding: 8px var(--tob-left) 16px; }
    html.tob-choices .tob-info { padding: 6px var(--tob-left) 24px; }
    html.tob-choices .tob-info-open .tob-caption, html.tob-choices .tob-info-open .tob-view { display: none; }
    html.tob-choices .tob-info-open .tob-pick { display: none; }
  }

  /* =====================================================================================================
     "Picker" widgets (cfg.picker): a drawing with a list of its parts beside it, as on the site. Choosing a part
     colours it turquoise in the drawing ("single": one at a time, underlined in the list) or shows and hides it
     ("toggle": blocks that start switched on). The colour rules below are the site's own (index.css), applied
     to the classes the artwork carries.
     ===================================================================================================== */
  .tob-picker .tob-pause { display: none; }
  .tob-picker .tob-view { display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: start; }
  .tob-picks { padding: 18px 8px 16px var(--tob-left); display: flex; flex-direction: column; align-items: flex-start; font: 400 12px/16px var(--tob-mono); }
  .tob-picks button { display: flex; align-items: center; gap: 10px; min-height: 31px; padding: 4px 0; color: #000; letter-spacing: .6px; }
  .tob-picks button svg { width: 28px; height: 30px; flex: none; margin: 3px 0 3px -4px; color: #000; overflow: visible; }
  .tob-picks button span { padding-bottom: 2px; border-bottom: 4px solid transparent; transition: border-color .15s, color .15s; }
  .tob-picks button[aria-pressed="true"] span { border-bottom-color: var(--tob-highlight); }
  .tob-picker-toggle .tob-picks { gap: 10px; }
  .tob-picker-toggle .tob-picks button {
    flex-direction: column; justify-content: center; gap: 6px; width: 116px; min-height: 76px; padding: 12px 8px 8px;
    border: 1px solid #000; text-align: center; transition: background-color .15s, border-color .15s, color .15s;
  }
  .tob-picker-toggle .tob-picks button svg { width: 84px; height: 38px; margin: 0; }
  .tob-picker-toggle .tob-picks button span { border: 0; padding: 0; }
  .tob-picker-toggle .tob-picks button[aria-pressed="true"] { background: var(--tob-highlight); border-color: var(--tob-highlight); font-weight: 600; }
  @media (hover: hover) {
    .tob-picker-single .tob-picks button:hover { color: var(--tob-highlight); }
    .tob-picker-toggle .tob-picks button:hover { background: #fff; border-color: var(--tob-highlight); color: var(--tob-highlight); }
    .tob-picker-toggle .tob-picks button[aria-pressed="true"]:hover { color: #000; background: var(--tob-highlight); }
  }
  @media (pointer: coarse) { .tob-picker-single .tob-picks button { min-height: 44px; } }
  @media (max-width: 470px) {            /* narrow column or phone: the list goes above the drawing */
    .tob-picker .tob-view { display: block; }
    .tob-picks { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0 14px; padding: 6px var(--tob-left) 4px; }
    .tob-picker-toggle .tob-picks { display: flex; flex-direction: row; }
    .tob-picker-toggle .tob-picks { gap: 8px; }
    .tob-picker-toggle .tob-picks button { width: auto; flex: 1 1 0; min-width: 0; }
  }
  /* the site's colouring of a chosen part */
  .tob-picker .highlighterIlluFill > g > path, .tob-picker .highlighterIlluStroke > g > path,
  .tob-picker .highlighterIlluFill > path, .tob-picker .highlighterIlluStroke > path { transition: fill .5s, fill-opacity .5s, stroke .5s, stroke-opacity .5s; }
  .tob-picker .highlighterIlluFill.highlightIllu > *, .tob-picker .highlightIllu > .highlighterIlluFill > *,
  .tob-picker .highlightIllu > .highlighterIlluFill, .tob-picker .highlighterIlluFill.highlightIllu > * > *,
  .tob-picker .highlightIllu > *, .tob-picker .highlightIllu > * > *.highlighterIlluFill { fill: var(--tob-highlight); fill-opacity: 1; }
  .tob-picker .highlighterIlluBorder.highlightIllu > *, .tob-picker .highlightIllu > .highlighterIlluBorder > *,
  .tob-picker .highlightIllu > .highlighterIlluBorder, .tob-picker .highlighterIlluBorder.highlightIllu > * > *,
  .tob-picker .highlighterIlluStroke.highlightIllu > *, .tob-picker .highlightIllu > .highlighterIlluStroke > *,
  .tob-picker .highlightIllu > .highlighterIlluStroke, .tob-picker .highlighterIlluStroke.highlightIllu > * > * { stroke: var(--tob-highlight); stroke-width: 3; stroke-opacity: 1; }
  .tob-picker .highlighterDisplay > * { opacity: 0; transition: opacity .5s; }
  .tob-picker .highlighterDisplay.highlightIllu > * { opacity: 1; }
  .tob-picker .highlighterIlluDisplay { opacity: 0; transition: opacity .3s; }
  .tob-picker .highlighterIlluDisplay.active, .tob-picker .highlighterIlluDisplay.highlightIllu { opacity: 1; }

  /* ---------- "plain" widgets (cfg.plain): one continuous loop, no steps or captions; a key to the symbols ---------- */
  .tob-key[hidden] { display: none; }
  .tob-plain .tob-caption, .tob-plain .tob-dots, .tob-plain .tob-steps { display: none !important; }
  .tob-plain .tob-head { padding-bottom: 6px; }
  .tob-plain .tob-tools .tob-ctl { width: 32px; height: 32px; }
  .tob-keyed .tob-view { display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: center; }
  .tob-key { padding: 8px var(--tob-left) 8px 0; font: 400 12px/15px var(--tob-mono); }
  .tob-key ul { display: grid; gap: 9px; }
  .tob-key li { display: flex; align-items: center; gap: 9px; }
  .tob-key svg { width: 55px; height: 25px; flex: none; color: currentColor; overflow: visible; }
  .tob-key-title { font-weight: 600; margin: 0 0 10px; }
  @media (max-width: 470px) {            /* narrow column or phone: the key goes under the animation */
    .tob-keyed .tob-view { display: block; }
    .tob-key { padding: 2px var(--tob-left) 14px; font-size: 11.5px; letter-spacing: 0; }
    .tob-key li { gap: 7px; }
    .tob-key ul { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px 10px; }
    .tob-key svg { width: 40px; height: 18px; }
  }
  @media (pointer: coarse) { .tob-plain .tob-tools .tob-ctl { width: 44px; height: 44px; } }
</style>
</head>
<body>

<div class="tob" id="tob-widget">
  <section class="tob-stage" aria-label="Animation">
    <div class="tob-head">
      <h1 class="tob-title" id="tob-title"></h1>
      <div class="tob-tools">
        <div class="tob-seg" id="tob-cond" role="group" aria-label="Condition" hidden></div>
        <button class="tob-icon tob-info-btn" id="tob-info-btn" type="button" aria-expanded="false" aria-controls="tob-info" aria-label="Show explanation">
          <svg viewBox="0 0 21 21" aria-hidden="true"><polygon points="15.76 9.81 11.19 9.81 11.19 5.24 9.81 5.24 9.81 9.81 5.24 9.81 5.24 11.19 9.81 11.19 9.81 15.76 11.19 15.76 11.19 11.19 15.76 11.19 15.76 9.81"/></svg>
        </button>
        <button class="tob-icon tob-narr-btn" id="tob-narr-btn" type="button" aria-pressed="false" aria-label="Turn narration on" title="Turn narration on">
          <svg viewBox="0 0 21 21" aria-hidden="true"><path d="M5 8.4h2.6l3.4-2.9v10l-3.4-2.9H5z"/><path class="ln" d="M13.2 8.3a3.1 3.1 0 0 1 0 4.4M15 6.4a5.8 5.8 0 0 1 0 8.2"/><path class="off" d="M13.4 8.6l3.4 3.8M16.8 8.6l-3.4 3.8"/></svg>
        </button>
      </div>
    </div>
    <div class="tob-body">
      <div class="tob-info" id="tob-info"><p id="tob-info-text"></p></div>
      <div class="tob-caption tob-dim">
        <div class="tob-caption-text" id="tob-caption-text" aria-live="polite"></div>
        <div class="tob-nav">
          <span class="tob-count" id="tob-count"></span>
          <button class="tob-icon tob-ctl tob-prev" id="tob-prev" type="button" aria-label="Previous step" title="Previous step">
            <svg viewBox="0 0 21 21" aria-hidden="true"><path d="m6.4,13.58l.95-.95,1.71,1.71.83.99.06-.03-.11-1.9V3.99s1.34,0,1.34,0v9.4s-.11,1.9-.11,1.9l.06.03.83-.99,1.71-1.71.95.95-4.1,4.1-4.1-4.1Z"/></svg>
          </button>
          <button class="tob-icon tob-ctl tob-pause" id="tob-pause" type="button" aria-pressed="false" aria-label="Pause animation" title="Pause animation">
