</script>

<script>
(function () {
  "use strict";
  var cfg = JSON.parse(document.getElementById("tob-config").textContent);
  // A widget has one animation, or several "conditions" (e.g. Dark / Light) that the reader switches between.
  // Each condition has its own animation data, steps and narration; everything else is shared.
  var conds = cfg.conditions || [{ label: null, steps: cfg.steps, loops: cfg.loops, enter: cfg.enter, viewBox: cfg.viewBox,
                                   narration: cfg.narration, narrationAudio: cfg.narrationAudio }];
  conds.forEach(function (c, i) {
    c.data = JSON.parse(document.getElementById("tob-animation" + (i ? "-" + (i + 1) : "")).textContent);
    c.anim = null; c.box = null; c.presence = null; c.players = []; c.loaded = false;
  });
  // the active condition's values (re-pointed by adopt() when the reader switches condition)
  var cond, data, loops, enter, steps, nSteps, anim, narration, clips, players, presence;
  function adopt(c) {
    cond = c; data = c.data; anim = c.anim; presence = c.presence;
    loops = c.loops;                     // step i repeats loops[i][0] -> loops[i][1]
    enter = c.enter;                     // frame to start from when step i is reached from step i - 1
    steps = c.steps; nSteps = steps.length;
    narration = c.narration || []; clips = c.narrationAudio || []; players = c.players;
  }
  var narrow = window.matchMedia ? window.matchMedia("(max-width: 700px)") : { matches: false };
  var single = cfg.layout === "single";  // one column at every width (widgets that take half a page)

  var $ = function (id) { return document.getElementById(id); };
  var root = $("tob-widget");
  var canvas = $("tob-canvas");
  $("tob-title").textContent = cfg.title;
  canvas.setAttribute("aria-label", cfg.title + " animation");

  if (cfg.stageColor) canvas.style.background = cfg.stageColor;
  // "plain" widgets play one continuous loop: no captions or steps, and the pause button moves up beside the switch
  if (cfg.plain) {
    document.documentElement.classList.add("tob-plain");
    document.querySelector(".tob-tools").appendChild($("tob-pause"));
  }
  // key to the symbols used in the drawing (not clickable, unlike the legend)
  if (cfg.key && cfg.key.length) {
    document.documentElement.classList.add("tob-keyed");
    cfg.key.forEach(function (k) {
      var li = document.createElement("li");
      li.innerHTML = (k.icon || "") + "<span>" + k.label + "</span>";
      $("tob-key-list").appendChild(li);
    });
    $("tob-key").hidden = false;
  }
  conds.forEach(function (c, i) {
    c.box = document.createElement("div");
    c.box.className = "tob-anim";
    c.box.hidden = i > 0;
    canvas.appendChild(c.box);
    c.anim = lottie.loadAnimation({
      container: c.box,
      renderer: "svg",
      loop: true,                        // as on the original site: the current step repeats until the reader moves on
      autoplay: false,
      animationData: c.data,
      rendererSettings: { progressiveLoad: false, preserveAspectRatio: "xMidYMid meet" }
    });
    c.anim.setSubframe(true);
    if (cfg.speed) c.anim.setSpeed(cfg.speed);
    c.anim.addEventListener("drawnFrame", function () { if (c === cond) { syncHalos(); placeFollow(); } });
  });
  adopt(conds[0]);
  function artSvg() { return cond.box.querySelector("svg"); }
  // frame number in the animation's own timeline (the player counts from the start of the segment being played)
  function absFrame() { return anim.currentFrame + (anim.firstFrame || 0); }
  function inRanges(f, ranges) {
    if (!ranges) return true;
    for (var i = 0; i < ranges.length; i++) if (f >= ranges[i][0] && f < ranges[i][1]) return true;
    return false;
  }
  // every element of the active animation that belongs to a legend entry (an entry may list several class names)
  function partsOf(cls) {
    var out = [], svg = artSvg();
    if (!svg) return out;
    cls.split(" ").forEach(function (c) { if (c) Array.prototype.push.apply(out, svg.getElementsByClassName(c)); });
    return out;
  }

  var current = 0;
  var onScreen = true;

  // ----- steps list (rebuilt when the condition changes) -----
  var stepButtons = [], dotButtons = [];
  function buildSteps() {
  stepButtons = []; dotButtons = [];
  $("tob-steps").textContent = ""; $("tob-dots").textContent = "";
  steps.forEach(function (text, i) {
    var li = document.createElement("li");
    var b = document.createElement("button");
    b.type = "button";
    b.className = "tob-step";
    var n = document.createElement("span");
    n.className = "tob-step-num";
    n.textContent = String(i + 1);
    var t = document.createElement("span");
    t.textContent = text;
    b.appendChild(n); b.appendChild(t);
    b.addEventListener("click", function () { playStep(i, i === current + 1); });
    li.appendChild(b);
    $("tob-steps").appendChild(li);
    stepButtons.push(b);
    // the same step as a numbered button (shown on phones instead of the list)
    var d = document.createElement("button");
    d.type = "button";
    d.className = "tob-dot";
    d.textContent = (cfg.dotLabels && cfg.dotLabels[i]) || String(i + 1);
    d.setAttribute("aria-label", "Step " + (i + 1) + ": " + text);
    d.addEventListener("click", function () { playStep(i, i === current + 1); });
    $("tob-dots").appendChild(d);
    dotButtons.push(d);
  });
  }
  buildSteps();

  // ----- condition switch -----
  var condButtons = [];
  function setCondition(i) {
    if (conds[i] === cond) return;
    stopNarration();
    anim.pause();
    cond.box.hidden = true;
    adopt(conds[i]);
    cond.box.hidden = false;
    condButtons.forEach(function (b, k) { b.setAttribute("aria-pressed", String(k === i)); });
    buildSteps();
    applyFraming();
    if (!cond.presence) { try { computePresence(); } catch (e) { presence = cond.presence = null; } }
    applyHighlight();
    playStep(0);                         // a different condition starts again from its first step
  }
  if (conds.length > 1) {
    conds.forEach(function (c, i) {
      var b = document.createElement("button");
      b.type = "button"; b.textContent = c.label;
      b.setAttribute("aria-pressed", String(i === 0));
      b.addEventListener("click", function () { setCondition(i); });
      $("tob-cond").appendChild(b);
      condButtons.push(b);
    });
    $("tob-cond").hidden = false;
  }

  // ----- "hold" mode: every step is a still picture (cfg.hold[i].at); a switch plays across to a second picture
  // (cfg.hold[i].alt, e.g. the same eye with a corrective lens) and back -----
  var hold = cfg.hold || null, altOn = false, altButtons = [], altPlayers = [];
  function renderAlt() {
    var has = hold[current].alt != null;
    altButtons.forEach(function (b, k) { b.disabled = !has; b.setAttribute("aria-pressed", String(has && (k === 1) === altOn)); });
  }
  function setAlt(on) {
    var h = hold[current];
    if (h.alt == null || on === altOn) return;
    altOn = on;
    renderCaption(); renderAlt();
    anim.loop = false;
    anim.playSegments(on ? [h.at, h.alt] : [h.alt, h.at], true);
    narrate();
  }
  if (hold) {
    document.documentElement.classList.add("tob-hold");
    (cfg.altLabels || ["Off", "On"]).forEach(function (label, k) {
      var b = document.createElement("button");
      b.type = "button"; b.textContent = label;
      b.addEventListener("click", function () { setAlt(k === 1); });
      $("tob-cond").appendChild(b);
      altButtons.push(b);
    });
    $("tob-cond").hidden = false;
  }
  // "choices" layout: the site's block of buttons, one per state, each with its "Corrected" button beside it
  var picks = [];
  function choose(i, alt) {
    if (i === current) { setAlt(alt); return; }      // same state: play the lens in or out
    altOn = alt && hold[i].alt != null;
    playStep(i);
  }
  if (hold && cfg.layout === "choices") {
    document.documentElement.classList.add("tob-choices");
    var pick = document.createElement("div");
    pick.className = "tob-pick tob-dim";
    pick.setAttribute("role", "group"); pick.setAttribute("aria-label", "Eye");
    steps.forEach(function (name, i) {
      var row = document.createElement("div"); row.className = "tob-pick-row";
      var b = document.createElement("button"); b.type = "button"; b.textContent = name;
      b.addEventListener("click", function () { choose(i, false); });
      row.appendChild(b);
      var a = null;
      if (hold[i].alt != null) {
        a = document.createElement("button"); a.type = "button"; a.className = "tob-pick-alt";
        a.textContent = (cfg.altLabels || [])[1] || "On";
        a.setAttribute("aria-label", name + ", " + a.textContent.toLowerCase());
        a.addEventListener("click", function () { choose(i, true); });
        row.appendChild(a);
      } else b.classList.add("is-wide");
      pick.appendChild(row);
      picks.push({ main: b, alt: a });
    });
    var cap = document.querySelector(".tob-caption");
    cap.parentNode.insertBefore(pick, cap);
  }
  function renderPicks() {
    picks.forEach(function (p, i) {
      var here = i === current;
      p.main.classList.toggle("is-on", here && !altOn);
      p.main.classList.toggle("is-row", here && altOn);
      p.main.setAttribute("aria-pressed", String(here && !altOn));
      if (p.alt) { p.alt.classList.toggle("is-on", here && altOn); p.alt.setAttribute("aria-pressed", String(here && altOn)); }
    });
  }
  function captionOf(i, alt) {
    return (alt && cfg.captionsAlt && cfg.captionsAlt[i]) || (cfg.captions && cfg.captions[i]) || steps[i];
  }

  function renderCaption() {
    $("tob-caption-text").textContent = captionOf(current, altOn);
    renderPicks();
    $("tob-count").textContent = (current + 1) + " / " + nSteps;
    $("tob-count").setAttribute("aria-label", "Step " + (current + 1) + " of " + nSteps);
    stepButtons.concat(dotButtons).forEach(function (b, i) {
      if (i % nSteps === current) b.setAttribute("aria-current", "step"); else b.removeAttribute("aria-current");
    });
    renderPresence();
  }

  // Some changes in the artwork last a single frame and sit exactly on a step boundary (e.g. the voltmeter
  // switching off as step 2 begins). They are transitions between steps, so they are played once when a step
  // is reached from the one before it, and kept out of the repeating part.
  function playStep(i, fromPrevious) {
    current = ((i % nSteps) + nSteps) % nSteps;
    if (hold) {
      if (hold[current].alt == null) altOn = false;
      renderCaption(); renderAlt();
      anim.loop = false;
      anim.resetSegments(true);
      anim.goToAndStop(altOn ? hold[current].alt : hold[current].at, true);
      narrate();
      return;
    }
    renderCaption();
    var loop = loops[current];
    if (fromPrevious && enter[current] !== loop[0]) anim.playSegments([[enter[current], loop[1]], loop], true);
    else anim.playSegments(loop, true);
    setPaused(false);
    if (!onScreen) anim.pause();
    narrate();
  }

  // ----- pause / resume (moving to another step resumes) -----
  var userPaused = false;
  function setPaused(p) {
    userPaused = p;
    var btn = $("tob-pause"), label = p ? "Play animation" : "Pause animation";
    btn.setAttribute("aria-pressed", String(p));
    btn.setAttribute("aria-label", label); btn.title = label;
  }
  $("tob-pause").addEventListener("click", function () {
    setPaused(!userPaused);
    if (userPaused) anim.pause(); else if (onScreen) anim.play();
  });
  $("tob-prev").addEventListener("click", function () { playStep(current - 1); });

  // ----- optional spoken narration (off until the reader turns it on) -----
  // Plays the clip in cfg.narrationAudio[i] (URL or data: URI) when there is one; otherwise the browser's own
  // text-to-speech voice reads cfg.narration[i]. cfg.narration is also the transcript of the clips.
  var synth = ("speechSynthesis" in window && "SpeechSynthesisUtterance" in window) ? window.speechSynthesis : null;
  var narrBtn = $("tob-narr-btn");
  var narrOn = false, voice = null, player = null;
  // Preferred voice: a British woman. Browsers do not report a voice's gender, so known voice names are
  // matched instead (Windows/Edge, Chrome, macOS/iOS). Order of preference:
  //   1. a known female en-GB voice   2. any en-GB voice that is not a known male one
  //   3. a known female English voice of another accent   4. whatever English voice the device offers
  var GB_FEMALE = /sonia|libby|maisie|hollie|bella|olivia|abbi|mia\b|hazel|susan|google uk english female|kate|serena|martha|stephanie|fiona|flo\b|shelley|sandy|amy|emma|female/i;
  var MALE = /\bmale\b|ryan|george|thomas|oliver|noah|elliot|ethan|alfie|daniel|arthur|malcolm|eddy|reed|rocko|grandpa|ralph|albert|fred|brian|david|mark|guy|james|aaron|gordon/i;
  var EN_FEMALE = /samantha|zira|jenny|aria|michelle|ava\b|allison|susan|karen|moira|tessa|victoria|google us english|female/i;
  function pickVoice() {
    if (!synth) return;
    var score = function (v) {
      var gb = /^en[-_]GB/i.test(v.lang), male = MALE.test(v.name) && !/female/i.test(v.name);
      var tier = gb && GB_FEMALE.test(v.name) && !male ? 400 : gb && !male ? 300 : EN_FEMALE.test(v.name) && !male ? 200 : gb ? 150 : 100;
      return tier + (/natural|neural|premium|enhanced/i.test(v.name) ? 20 : 0) + (v.localService ? 0 : 5) + (v.default ? 1 : 0);
    };
    var vs = synth.getVoices().filter(function (v) { return /^en([-_]|$)/i.test(v.lang); });
    vs.sort(function (a, b) { return score(b) - score(a); });
    voice = vs[0] || null;
  }
  function setSpeaking(on) { narrBtn.classList.toggle("is-speaking", on); }
  function stopNarration() {
    if (synth) synth.cancel();
    if (player) { player.pause(); player = null; }
    setSpeaking(false);
  }
  function narrate() {
    if (!narrOn) return;
    stopNarration();
    var step = current, alt = !!(hold && altOn);
    var src = alt ? (cfg.narrationAudioAlt || [])[step] : clips[step];
    var cache = alt ? altPlayers : players;
    var text = alt ? (cfg.narrationAlt || [])[step] : narration[step];
    if (src) {
      player = cache[step] || (cache[step] = new Audio(src));
      player.onended = function () { setSpeaking(false); };
      try { player.currentTime = 0; } catch (e) {}
      var started = player.play();
      setSpeaking(true);
      if (started && started.catch) started.catch(function () { setSpeaking(false); });
      return;
    }
    if (!synth || !text) return;
    var u = new SpeechSynthesisUtterance(text);
    if (!voice) pickVoice();                       // voices can arrive late on some browsers
    u.lang = (voice && voice.lang.replace("_", "-")) || "en-GB";
    if (voice) u.voice = voice;
    u.rate = 0.95;
    u.onstart = function () { setSpeaking(true); };
    u.onend = u.onerror = function () { if (current === step) setSpeaking(false); };
    synth.speak(u);
  }
  function setNarration(on) {
    narrOn = on;
    narrBtn.setAttribute("aria-pressed", String(on));
    var label = on ? "Turn narration off" : "Turn narration on";
    narrBtn.setAttribute("aria-label", label); narrBtn.title = label;
    if (on) narrate(); else stopNarration();
  }
  if ((synth && narration.length) || clips.length) {
    pickVoice();
    if (synth && synth.addEventListener) synth.addEventListener("voiceschanged", pickVoice);
    narrBtn.addEventListener("click", function () { setNarration(!narrOn); });
    window.addEventListener("pagehide", stopNarration);
  } else {
    narrBtn.style.display = "none";
  }
  $("tob-next").addEventListener("click", function () { playStep(current + 1, true); });

  // ----- info text ("+" button) -----
  var infoOpen = false;
  // Where the explanation is laid over the animation, the area under it is made tall enough for the whole text,
  // so the reader never has to scroll inside the panel (the widget simply gets taller while it is open).
  function fitInfo() {
    var body = document.querySelector(".tob-body"), info = $("tob-info");
    body.style.minHeight = "";
    if (infoOpen && getComputedStyle(info).position === "absolute") body.style.minHeight = Math.ceil(info.scrollHeight) + "px";
  }
  function setInfo(open) {
    infoOpen = open;
