  window.addEventListener("resize", fitInfo);
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(fitInfo);
  if (cfg.infoText) {
    $("tob-info-text").innerHTML = cfg.infoText;
    $("tob-info-btn").addEventListener("click", function () { setInfo(!infoOpen); });
    setInfo(!!cfg.infoOpen);
  } else {
    $("tob-info-btn").style.display = "none";
  }

  // ----- legend / highlighting -----
  var active = null;
  var chips = [];
  // ----- highlight outline -----
  // The outline is drawn in a separate, transparent SVG laid exactly over the animation, on its own layer.
  // Nothing inside the animation's own SVG is touched when a legend button is pressed, so the browser never
  // redraws the picture itself (redrawing it shifts its edges by a fraction of a pixel, which showed up as the
