  // several overlapping shapes (cGMP, GMP).
  var NS = "http://www.w3.org/2000/svg";
  var overlay = null, haloGroup = null, maskGroup = null, maskRect = null;
  var halos = [];                        // per highlighted layer: { layer, halo: [[orig, copy]...], sil: [[orig, copy]...] }
