  // In the book (window.OB) the frame is as tall as the widget reports, so window.innerHeight is no
  // measure of the screen (it follows the frame): size against a 700px frame, the book's figure pane on a laptop.
  function frameHeight() { return window.OB ? 700 : window.innerHeight; }
  function applyFraming() {
