</script>
</body>
</html>
$w$,
  'published')
on conflict (slug) do update
  set title = excluded.title, description = excluded.description, author = excluded.author,
      ramp = excluded.ramp, html = excluded.html, status = excluded.status, updated_at = now();

insert into public.widget_uploads (slug, title, description, author, ramp, html, status)
values (
  'retina-retinabox',
  $t$RetINaBox$t$,
  $t$Build a retinal circuit: wire photoreceptors, bipolar and ganglion cells and watch the circuit turn a light stimulus into spikes. Version 3, with guided tutorials.$t$,
  $t$Stuart Trenholm$t$,
  'perc',
  $w$<!DOCTYPE html>
<!--
  Open Brain upload (OPENBRAIN-141). Stuart Trenholm's 2026-10-01 RetINaBox
  v3 ("retinabox-web.html", with the guided tutorials), brought onto the widget kit
  with these edits only: the surface, hairline and font variables read the
  book's tokens with the original values as fallbacks (var(--ob-paper, …),
  var(--ob-line, …), var(--ob-font-sans, …)). The cell colours are the
  artwork's and stay. Everything else is as sent; the byte-for-byte original
  is src/widgets/source/retinabox-web.html.
-->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>RetINaBox &mdash; interactive retinal circuit</title>
<style>
/* ===========================================================================
   RetINaBox, web edition.
   Artwork, palette and layout follow the desktop application:
   GUI/Graphics/*.svg, GUI/styles.py, GUI/interaction_manager.py
   =========================================================================== */
:root{
  --blue:#1A83C9; --red:#CD1916; --orange:#E94D15;
  --lightGreen:#3D783F; --darkGreen:#1D341E; --black:#000000;
  --darkBrown:#593B25; --lightBrown:#B67E54; --yellow:#DEB33D;
  --gray:#BDBFB6; --lightGray:#E0E0E0; --lighterGray:#F2F2F2; --white:var(--ob-paper,#F5F3F3);
  --line:var(--ob-line,#CCCCCC);
  --font:var(--ob-font-sans,'Asap','Asap Condensed',ui-sans-serif,system-ui,'Segoe UI',Roboto,Arial,sans-serif);
}
*,*::before,*::after{box-sizing:border-box}

.rb{
  font-family:var(--font); color:var(--black); background:var(--white);
  border:1px solid var(--line); border-radius:8px;
  max-width:1180px; margin:0 auto; overflow:hidden; line-height:1.4;
  -webkit-font-smoothing:antialiased;
}
.rb button,.rb select,.rb input{font-family:inherit;color:inherit}
.rb :focus-visible{outline:2px solid var(--orange);outline-offset:2px}

/* ---------- title bar ---------- */
.rb-bar{
  display:flex;align-items:center;gap:.6rem;flex-wrap:wrap;padding:.5rem .8rem;
  background:var(--lighterGray);border-bottom:1px solid var(--line);
}
.rb-bar .rb-logo{width:44px;height:44px;flex:none}
.rb-bar h1{font-size:1.5rem;font-weight:700;margin:0;letter-spacing:.01em}
.rb-bar h1 i{font-style:normal}
.rb-bar .rb-sp{flex:1 1 0}
.rb-ob{display:flex;align-items:center;flex:0 0 auto;text-decoration:none}
.rb-ob img{height:52px;width:auto;display:block}
.rb-brand{display:flex;align-items:center;gap:.5rem;flex:0 0 auto}
@media (max-width:900px){
  .rb-ob img{height:38px}
  .rb-bar .rb-logo{width:32px;height:32px}
  .rb-bar h1{font-size:1.15rem}
}
@media (max-width:640px){
  .rb-bar .rb-sp{flex-basis:auto}
  .rb-ob img{height:32px}
  .rb-bar .rb-logo{width:26px;height:26px}
  .rb-bar h1{font-size:1rem}
}
.rb-bar select{
  font-size:.82rem;padding:.28rem .4rem;border:1px solid var(--gray);
  border-radius:4px;background:#fff;max-width:230px;
}

/* ---------- three panels, as in the desktop app ---------- */
.rb-panels{display:grid;grid-template-columns:250px 320px minmax(0,1fr);gap:0}
@media (max-width:1000px){.rb-panels{grid-template-columns:250px minmax(0,1fr)}}
@media (max-width:700px){.rb-panels{grid-template-columns:1fr}}

.rb-panel{padding:.7rem .8rem 1rem;border-right:1px solid var(--line);min-width:0}
.rb-panel:last-child{border-right:0}
@media (max-width:1000px){
  .rb-panel:nth-child(2){border-right:0}
  .rb-panel:nth-child(3){grid-column:1 / -1;border-top:1px solid var(--line)}
}
@media (max-width:700px){
  .rb-panel{border-right:0;border-top:1px solid var(--line)}
  .rb-panel:first-child{border-top:0}
  .rb-panel:nth-child(3){grid-column:auto}
}
.rb-title{
  text-align:center;font-size:.82rem;color:#444;margin:0 0 .6rem;
  padding-bottom:.35rem;border-bottom:1px solid var(--line);
}

/* ---------- legends ---------- */
.rb-leg{
  display:flex;flex-wrap:wrap;gap:.45rem .6rem;justify-content:center;
  font-size:.7rem;color:#333;margin-bottom:.5rem;
}
.rb-leg span{display:inline-flex;align-items:center;gap:.25rem}
.rb-leg .sw{width:12px;height:12px;border-radius:50%;display:block}
.rb-leg .bar{width:20px;height:3px;border-radius:2px;display:block}
.rb-leg svg{width:13px;height:15px;display:block}

/* ---------- stimulus lamps ---------- */
.rb-grid{
  display:grid;grid-template-columns:repeat(3,1fr);gap:.35rem;
  background:var(--lighterGray);border:1px solid var(--gray);border-radius:5px;
  padding:.5rem;margin:0 auto .7rem;width:max-content;
}
.rb-lamp{
  background:none;border:0;padding:2px 4px 0;cursor:pointer;border-radius:4px;
  display:flex;flex-direction:column;align-items:center;gap:1px;
}
.rb-lamp:hover{background:var(--lightGray)}
.rb-lamp svg{width:34px;height:40px;display:block}
.rb-lamp b{font-weight:400;font-size:.66rem;color:#555}

/* ---------- controls ---------- */
.rb-btnrow{display:flex;gap:.4rem;margin-bottom:.5rem}
.rb-btn{
  flex:1;padding:.32rem .4rem;font-size:.78rem;cursor:pointer;
  background:var(--lighterGray);border:1px solid var(--gray);border-radius:5px;
}
.rb-btn:hover{background:var(--lightGray)}
.rb-run{
  width:100%;padding:.45rem;font-size:.84rem;font-weight:600;color:#fff;cursor:pointer;
  background:var(--blue);border:0;border-radius:5px;margin-bottom:.7rem;
}
.rb-run:hover{filter:brightness(1.08)}
.rb-run.is-on{background:var(--lightBrown);color:#2E1D0E}

.rb-opt{display:flex;align-items:center;gap:.5rem;font-size:.78rem;margin-bottom:.4rem;flex-wrap:wrap}
/* display:flex beats the UA rule for [hidden], so restore it explicitly */
.rb-opt[hidden]{display:none}
.rb-opt > b{font-weight:400;color:#333;min-width:62px}
.rb-radio{display:inline-flex;align-items:center;gap:.25rem;cursor:pointer}
.rb-radio input{margin:0;accent-color:var(--darkBrown)}
.rb-num{width:52px;padding:.18rem .25rem;font-size:.8rem;border:1px solid var(--gray);border-radius:3px;background:#fff}

/* ---------- neuron widget ---------- */
.rb-neuron{
  background:var(--lighterGray);border:1px solid var(--lightGray);border-radius:5px;
  padding:.3rem;margin-bottom:.35rem;
}
.rb-neuron svg{width:100%;height:auto;display:block}
.rb-dot{cursor:pointer}
.rb-dot:hover .rb-dot-c{stroke:var(--black);stroke-width:2}
.rb-sep{border:0;border-top:1px solid var(--line);margin:.7rem 0}

/* ---------- scope ---------- */
.rb-scope{width:100%}
.rb-scope canvas{display:block;width:100%;height:auto}

/* ---------- delay dialog ---------- */
.rb-modal{
  position:absolute;inset:0;background:rgba(0,0,0,.35);
  display:flex;align-items:center;justify-content:center;padding:1rem;z-index:20;
}
.rb-modal[hidden]{display:none}
.rb-sheet{
  background:var(--white);border:1px solid var(--gray);border-radius:6px;
  padding:.8rem;max-width:430px;width:100%;max-height:100%;overflow:auto;
  box-shadow:0 8px 30px rgba(0,0,0,.3);
}
.rb-sheet h2{font-size:.9rem;margin:0 0 .6rem;text-align:center;font-weight:700}
.rb-units{display:grid;grid-template-columns:repeat(3,1fr);gap:.4rem}
.rb-unit{
  border:1px solid var(--lightGray);border-radius:5px;background:var(--lighterGray);
  padding:.4rem .3rem;text-align:center;
}
.rb-pm{
  width:30px;height:30px;border-radius:50%;border:0;cursor:pointer;
  font-size:1rem;font-weight:700;color:#fff;background:var(--gray);line-height:1;
}
.rb-pm[data-state="excitatory"]{background:var(--red)}
.rb-pm[data-state="inhibitory"]{background:var(--blue)}
.rb-unit label{display:block;font-size:.62rem;color:#555;margin:.3rem 0 .1rem}
.rb-unit input[type=range]{width:100%;margin:0;accent-color:var(--darkBrown)}
.rb-unit input[type=range]:disabled{opacity:.4}
.rb-unit small{font-size:.58rem;color:#666;display:block}
.rb-close{
  width:100%;margin-top:.6rem;padding:.35rem;font-size:.8rem;cursor:pointer;
  background:var(--darkBrown);color:#fff;border:0;border-radius:5px;
}

.rb-foot{
  padding:.5rem .8rem .7rem;border-top:1px solid var(--line);
  background:var(--lighterGray);font-size:.7rem;color:#555;
}
.rb-foot a{color:var(--darkBrown)}


/* ---------- tabs ---------- */
.rb-tabs{display:flex;gap:2px;padding:.35rem .8rem 0;background:var(--lighterGray);
  border-bottom:1px solid var(--line)}
.rb-tab{padding:.35rem .8rem;font-size:.8rem;cursor:pointer;background:var(--lightGray);
  border:1px solid var(--line);border-bottom:0;border-radius:5px 5px 0 0;position:relative;top:1px}
.rb-tab[aria-selected="true"]{background:var(--white);font-weight:600}
.rb-mode[hidden]{display:none}

/* ---------- code breaker ---------- */
.rb-cb{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,3fr);gap:.8rem;padding:.8rem}
@media (max-width:860px){.rb-cb{grid-template-columns:1fr}}
.rb-box{border:1px solid var(--gray);border-radius:5px;padding:.6rem;background:var(--white)}
.rb-box > h3{font-size:.78rem;margin:-.95rem 0 .5rem .3rem;padding:0 .3rem;
  background:var(--white);display:inline-block;color:#444;font-weight:600}
.rb-code{display:flex;flex-wrap:wrap;gap:.3rem}
.rb-tok{width:74px;display:flex;flex-direction:column;align-items:center;gap:.25rem}
.rb-tok.sp{width:26px}
.rb-tok .pat{display:grid;grid-template-columns:repeat(3,1fr);gap:3px;padding:4px;
  background:var(--lightGray);border:1px solid #ddd;border-radius:3px}
.rb-tok .pat i{width:11px;height:11px;border-radius:2px;background:var(--white);
  border:1px solid var(--gray);display:block}
.rb-tok .pat i.on{background:var(--yellow);border-color:var(--darkBrown)}
.rb-tok select{width:56px;font-size:.75rem;padding:.1rem;border:1px solid var(--gray);
  border-radius:3px;background:var(--white)}
.rb-tok select.ok{border-color:var(--lightGreen);background:#E8F2E8}
.rb-tok select.no{border-color:var(--red);background:#FBEAEA}
.rb-tok b{font-size:1rem;padding-top:.6rem}
.rb-cipher{display:flex;gap:.8rem;justify-content:center;flex-wrap:wrap;margin-bottom:.6rem}
.rb-cipher figure{margin:0;text-align:center;font-size:.72rem}
.rb-cipher .pat{display:grid;grid-template-columns:repeat(3,1fr);gap:3px;padding:4px;
  background:var(--lightGray);border:1px solid #ddd;border-radius:3px;margin-bottom:.25rem}
.rb-cipher .pat i{width:13px;height:13px;border-radius:2px;background:var(--white);
  border:1px solid var(--gray);display:block}
.rb-cipher .pat i.on{background:var(--yellow);border-color:var(--darkBrown)}
table.rb-book{border-collapse:collapse;width:100%;font-size:.76rem}
table.rb-book th,table.rb-book td{border:1px solid var(--gray);padding:.2rem;text-align:center}
table.rb-book th{background:var(--lightGray);font-weight:600}
table.rb-book td:last-child{font-weight:700}
.rb-result{font-size:.8rem;text-align:center;margin:.5rem 0 0;min-height:1.2em}

/* ---------- document viewers ---------- */
.rb-doc{padding:.6rem .8rem .8rem}
.rb-docbar{display:flex;align-items:center;gap:.5rem;flex-wrap:wrap;margin-bottom:.5rem}
.rb-docbar h3{font-size:.85rem;margin:0;font-weight:700}
.rb-docbar .sp{flex:1}
.rb-docbar a{
  font-size:.76rem;padding:.28rem .6rem;border-radius:5px;text-decoration:none;
  border:1px solid var(--gray);background:var(--lighterGray);color:var(--black);
}
.rb-docbar a:hover{background:var(--lightGray)}
.rb-docbar a.primary{background:var(--blue);border-color:var(--blue);color:#fff}
.rb-frame{
  position:relative;border:1px solid var(--gray);border-radius:5px;overflow:hidden;
  background:var(--lighterGray);height:78vh;min-height:460px;
}
.rb-frame iframe{width:100%;height:100%;border:0;display:block;background:#fff}
.rb-frame .note{
  position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  text-align:center;padding:1.5rem;font-size:.8rem;color:#555;pointer-events:none;
}
.rb-dochint{font-size:.7rem;color:#666;margin:.4rem 0 0}
.rb-dochint a{color:var(--darkBrown)}

/* ---------- discovery mode ---------- */
.rb-dm{padding:.8rem}
.rb-dmbar{display:flex;flex-wrap:wrap;gap:.8rem;align-items:center;background:var(--darkGreen);
  color:#fff;border-radius:5px;padding:.4rem .7rem;font-size:.78rem;margin-bottom:.7rem}
.rb-dmbar select{font-size:.78rem;padding:.15rem .3rem;border-radius:3px;border:1px solid #555}
.rb-dmbar .val{font-family:ui-monospace,monospace;font-size:.95rem;color:#7CFF9B;font-weight:700}
.rb-dmbar button{padding:.25rem .7rem;font-size:.78rem;border:0;border-radius:4px;
  background:var(--gray);cursor:pointer;font-weight:600}
.rb-dmbar button:disabled{opacity:.5;cursor:default}
.rb-dmtop{display:grid;grid-template-columns:1fr 1fr;gap:.8rem;margin-bottom:.7rem}
@media (max-width:760px){.rb-dmtop,.rb-dmphases{grid-template-columns:1fr!important}}
.rb-dmphases{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}
.rb-phase{border:1px solid var(--gray);border-radius:5px;padding:.6rem;background:var(--lighterGray)}
.rb-phase > h3{font-size:.8rem;margin:0 0 .5rem;font-weight:700}
.rb-phase .rb-neuron{max-width:320px;margin-left:auto;margin-right:auto}
.rb-phase[data-locked="1"]{opacity:.45;pointer-events:none}
.rb-dmgrid{display:grid;grid-template-columns:repeat(3,44px);gap:5px;justify-content:center;
  margin-bottom:.5rem}
.rb-dmgrid button{height:44px;border:1px solid var(--gray);border-radius:4px;cursor:pointer;
  background:var(--white);font-size:.8rem}
.rb-dmgrid button[aria-pressed="true"]{background:var(--yellow);border-color:var(--darkBrown);font-weight:700}
.rb-dmtest{width:100%;margin-top:.5rem;padding:.35rem;font-size:.8rem;cursor:pointer;
  background:var(--darkBrown);color:#fff;border:0;border-radius:4px}
.rb-dmnote{font-size:.74rem;margin:.4rem 0 0;min-height:1.1em}
.rb-ok{color:var(--lightGreen);font-weight:600}
.rb-no{color:var(--red);font-weight:600}

@media (prefers-reduced-motion:reduce){ .rb *{transition:none!important} }

/* ---------- tutorials ---------- */
@supports (overflow:clip){ .rb{overflow:clip} }   
.rb-menus{display:grid;grid-template-columns:auto minmax(0,230px);gap:.3rem .4rem;align-items:center;flex:0 0 auto}
.rb-menus .rb-btn{flex:none;width:100%;white-space:nowrap}
.rb-menus select{max-width:none;width:100%}
/* while a tutorial is shown, its caption and controls replace the logo and title, so the widget keeps its height */
.rb-tourshow .rb-bar > .rb-ob,.rb-tourshow .rb-bar > .rb-sp,.rb-tourshow .rb-bar > .rb-brand{display:none}
.rb-tourbar{
  position:relative;z-index:40;flex:1 1 0;min-width:0;align-self:stretch;overflow:hidden;
  display:flex;align-items:center;gap:.8rem;margin:-.5rem 0 -.5rem -.8rem;padding:.4rem .7rem .5rem .8rem;
  background:var(--darkGreen);color:#fff;
}
.rb-tourbar[hidden]{display:none}
.rb-tourcap{flex:1 1 0;min-width:0;margin:0;font-size:.88rem;line-height:1.3}
.rb-tourctl{flex:0 0 auto;display:flex;flex-direction:column;gap:.3rem}
.rb-tourctl > div{display:flex;align-items:center;gap:.3rem}
.rb-tourctl > div > :last-child{flex:1}
#rb-tour-count{font-size:.74rem;opacity:.85;min-width:3.4em;text-align:center;font-variant-numeric:tabular-nums}
.rb .rb-tourctl button{
  font-size:.74rem;padding:.24rem .55rem;border-radius:4px;cursor:pointer;white-space:nowrap;
  border:1px solid rgba(255,255,255,.55);background:transparent;color:#fff;
}
.rb .rb-tourctl button:hover{background:rgba(255,255,255,.16)}
.rb-tourctl button[hidden]{display:none}
.rb-tourprog{position:absolute;left:0;bottom:0;height:3px;width:0;background:#00D9B8}
@media (max-width:1210px){ .rb-tourcap{font-size:.8rem} .rb-tourbar{gap:.6rem} }
/* when the header has scrolled out of view (tablets, phones, small windows) the caption pins to the top of the window */
.rb-tourpin .rb-tourbar{
  position:fixed;left:0;right:0;top:0;margin:0;flex:none;box-shadow:0 2px 8px rgba(0,0,0,.35);
  padding-left:max(.8rem,env(safe-area-inset-left));padding-right:max(.7rem,env(safe-area-inset-right));
}
.rb-tourpin .rb-tourcap{font-size:.8rem}
/* ...and shows whether each cell is firing, because the Signal Monitor may be off screen */
.rb-tourfire{display:none;gap:.25rem}
.rb-tourpin .rb-tourfire.is-lab{display:flex}
.rb-tourfire i{font-style:normal;font-size:.68rem;line-height:1;padding:.3rem .45rem;border-radius:10px;white-space:nowrap;
  border:1px solid rgba(255,255,255,.45);color:rgba(255,255,255,.6)}
.rb-tourfire i.on{color:#000;border-color:transparent}
.rb-tourfire i:nth-child(1).on{background:#6FCF73}
.rb-tourfire i:nth-child(2).on{background:var(--yellow)}
@media (pointer:coarse){ .rb .rb-tourctl button{padding:.36rem .7rem} }
@media (max-width:640px){
  .rb-tourpin .rb-tourbar{flex-wrap:wrap;gap:.35rem .8rem}
  .rb-tourpin .rb-tourcap{flex:1 1 100%}
  .rb-tourpin .rb-tourctl{flex-direction:row;flex-wrap:wrap}
}
#rb-tour-layer{position:absolute;inset:0;z-index:30;overflow:hidden;cursor:default}
#rb-tour-layer[hidden]{display:none}
#rb-tour-spot{position:absolute;left:0;top:0;width:100%;height:100%;display:block}
#rb-tour-cur{position:absolute;left:0;top:0;width:26px;height:26px;pointer-events:none;
  filter:drop-shadow(0 1px 2px rgba(0,0,0,.45));will-change:transform}
#rb-tour-rip{position:absolute;left:0;top:0;border-radius:50%;border:3px solid #00D9B8;
  background:rgba(0,217,184,.25);pointer-events:none;display:none}
#rb-tour-menu{position:absolute;background:#fff;border:1px solid #777;box-shadow:0 4px 14px rgba(0,0,0,.3);
  font-size:.82rem;padding:2px 0}
#rb-tour-menu[hidden]{display:none}
#rb-tour-menu div{padding:.2rem .6rem;white-space:nowrap}
#rb-tour-menu div.hov{background:#1A6FD0;color:#fff}

/* ---------- phones and tablets ---------- */
/* the Delays dialog is centred in the window, not in the (possibly much taller) widget */
.rb-modal{position:fixed}
.rb-tourpin .rb-modal{padding-top:5.6rem;align-items:flex-start}
/* short landscape screens (phones): keep a whole ganglion cell drawing on one screen */
@media (orientation:landscape) and (max-height:560px){
  #rb-neurons .rb-neuron{max-width:max(250px,calc((100vh - 150px) * 1.119));margin-left:auto;margin-right:auto}
  .rb-sheet{padding:.5rem}
  .rb-unit{padding:.25rem .3rem}
  .rb-unit label{margin:.15rem 0 0}
}
</style>
</head>
