  <div class="rb-bar">
    <!-- tutorial caption and controls: shown only while a tutorial plays, in place of the logo and title -->
    <div class="rb-tourbar" id="rb-tour-bar" hidden>
      <p class="rb-tourcap" id="rb-tour-cap" aria-live="polite"></p>
      <div class="rb-tourctl">
        <div>
          <button type="button" id="rb-tour-back" aria-label="Previous section" title="Previous section">&#9664;</button>
          <span id="rb-tour-count"></span>
          <button type="button" id="rb-tour-next" aria-label="Next section" title="Next section">&#9654;</button>
          <button type="button" id="rb-tour-pause">Pause</button>
        </div>
        <div>
          <span class="rb-tourfire" id="rb-tour-fire" aria-hidden="true"><i>RGC 1</i><i>RGC 2</i></span>
          <button type="button" id="rb-tour-mute">Mute</button>
          <button type="button" id="rb-tour-again">Restart</button>
          <button type="button" id="rb-tour-end">End tutorial</button>
        </div>
      </div>
      <div class="rb-tourprog" id="rb-tour-prog"></div>
    </div>
    <a class="rb-ob" href="https://theopenbrain.org" target="_blank" rel="noopener">
      <img src="data:image/png;base64," alt="The Open Brain — theopenbrain.org">
    </a>
    <div class="rb-sp"></div>
    <div class="rb-brand">
      <svg class="rb-logo" aria-hidden="true"><use href="#rb-logo"/></svg>
      <h1>Ret<i>IN</i>aBox</h1>
    </div>
    <div class="rb-sp"></div>
    <div class="rb-menus">
      <button type="button" class="rb-btn" id="rb-load">Load a circuit</button>
      <select id="rb-preset" aria-label="Circuit to load"></select>
      <button type="button" class="rb-btn" id="rb-tour-go">Play a tutorial</button>
      <select id="rb-tour-sel" aria-label="Tutorial to play"></select>
    </div>
  </div>

  <div class="rb-tabs" role="tablist">
    <button type="button" class="rb-tab" role="tab" data-mode="lab" aria-selected="true">RetINaBox Lab</button>
    <button type="button" class="rb-tab" role="tab" data-mode="cb"  aria-selected="false">Code Breaker</button>
    <button type="button" class="rb-tab" role="tab" data-mode="dm"  aria-selected="false">Discovery Mode</button>
    <button type="button" class="rb-tab" role="tab" data-mode="lp"  aria-selected="false">Lesson Plans</button>
    <button type="button" class="rb-tab" role="tab" data-mode="sl"  aria-selected="false">Teaching Slides</button>
  </div>

  <div class="rb-mode" id="rb-mode-lab">
  <div class="rb-panels">

    <!-- ============ Visual Stimulus Controller ============ -->
    <section class="rb-panel">
      <p class="rb-title">Visual Stimulus Controller</p>

      <div class="rb-leg">
        <span>Unselected:<svg viewBox="0 0 88 104"><use href="#led-unselected"/></svg></span>
        <span>Selected:<svg viewBox="0 0 88 104"><use href="#led-selected"/></svg></span>
        <span>Active:<svg viewBox="0 0 88 104"><use href="#led-on"/></svg></span>
      </div>

      <div class="rb-grid" id="rb-lamps" role="group" aria-label="Stimulus LED array"></div>

      <div class="rb-btnrow">
        <button type="button" class="rb-btn" id="rb-all">Select all</button>
        <button type="button" class="rb-btn" id="rb-none">Clear all</button>
      </div>
      <button type="button" class="rb-run" id="rb-run">Activate stimulus LEDs</button>

      <div class="rb-opt">
        <b>Mode:</b>
        <label class="rb-radio"><input type="radio" name="rb-mode" value="Static" checked> Static</label>
        <label class="rb-radio"><input type="radio" name="rb-mode" value="Motion"> Motion</label>
      </div>
      <div class="rb-opt" id="rb-dir-row" hidden>
        <b>Direction:</b>
        <label class="rb-radio"><input type="radio" name="rb-dir" value="Left"> Left</label>
        <label class="rb-radio"><input type="radio" name="rb-dir" value="Right" checked> Right</label>
      </div>
      <div class="rb-opt" id="rb-speed-row" hidden>
        <b>Speed:</b>
        <input type="range" id="rb-speed" min="0" max="2" step="1" value="1"
               style="flex:1;min-width:90px;accent-color:var(--darkBrown)">
        <span id="rb-speed-lbl" style="font-size:.74rem;color:#555;min-width:48px">Medium</span>
      </div>
    </section>

    <!-- ============ Connectivity Manager ============ -->
    <section class="rb-panel">
      <p class="rb-title">Connectivity Manager</p>

      <div class="rb-leg">
        <span>Silent:<i class="sw" style="background:var(--gray)"></i></span>
        <span>Excitatory:<i class="sw" style="background:var(--red)"></i></span>
        <span>Inhibitory:<i class="sw" style="background:var(--blue)"></i></span>
        <span>Delay:<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="11" fill="none" stroke="#333"/><path d="M12 5l6 12H6z" fill="#000"/></svg></span>
      </div>

      <div id="rb-neurons"></div>
    </section>

    <!-- ============ Signal Monitor ============ -->
    <section class="rb-panel">
      <p class="rb-title">Signal Monitor</p>
      <div class="rb-leg">
        <span><i class="bar" style="background:var(--red)"></i>Excitatory</span>
        <span><i class="bar" style="background:var(--blue)"></i>Inhibitory</span>
      </div>
      <div class="rb-scope">
        <canvas id="rb-canvas" role="img"
          aria-label="Rolling ten second recording of photoreceptor input, synaptic drive and ganglion cell output"></canvas>
      </div>
    </section>
  </div>

  </div><!-- /lab -->

  <!-- ================= Code Breaker ================= -->
  <div class="rb-mode" id="rb-mode-cb" hidden>
    <div style="padding:.6rem .8rem 0"><label style="font-size:.8rem">Challenge:
      <select id="cb-sel" style="font-size:.8rem;padding:.2rem;border:1px solid var(--gray);border-radius:4px"></select>
    </label></div>
    <div class="rb-cb">
      <div class="rb-box"><h3>Secret Code</h3><div class="rb-code" id="cb-code"></div></div>
      <div>
        <div class="rb-box"><h3>Cipher</h3>
          <div class="rb-cipher" id="cb-pref"></div>
          <table class="rb-book"><thead><tr><th>RGC1</th><th>RGC2</th><th>Letter</th></tr></thead>
            <tbody id="cb-book"></tbody></table>
        </div>
        <button type="button" class="rb-dmtest" id="cb-check">Check Answers</button>
        <p class="rb-result" id="cb-result"></p>
      </div>
    </div>
  </div>

  <!-- ================= Discovery Mode ================= -->
  <div class="rb-mode" id="rb-mode-dm" hidden>
    <div class="rb-dm">
      <div class="rb-dmbar">
        <span>Current Challenge:</span><select id="dm-sel"></select>
        <button type="button" id="dm-start">Start Challenge</button>
        <span>Points: <b class="val" id="dm-points">100</b></span>
        <span>Timer: <b class="val" id="dm-timer">00:00</b></span>
      </div>

      <div class="rb-dmtop">
        <div class="rb-box"><h3>Instructions</h3>
          <p style="font-size:.76rem;margin:0">1. Select and start a challenge from the menu above.<br>
          2. Complete phases 1 and 2.<br><br>
          Tip: watch the live RGC response to guide your progress.</p></div>
        <div class="rb-box"><h3>Live RGC Response</h3>
          <canvas id="dm-canvas" style="width:100%;height:auto;display:block"
            role="img" aria-label="Live RGC response"></canvas></div>
      </div>

      <div class="rb-dmphases">
        <div class="rb-phase" id="dm-p1" data-locked="1">
          <h3>Phase 1: Discover the Preferred Stimulus</h3>
          <div class="rb-dmgrid" id="dm-grid"></div>
          <div class="rb-opt"><b>Motion:</b>
            <select id="dm-motion"><option>Static</option><option>Moving</option></select></div>
          <div class="rb-opt"><b>Speed:</b><select id="dm-speed" disabled><option>---</option></select></div>
          <div class="rb-opt"><b>Direction:</b><select id="dm-dir" disabled><option>---</option></select></div>
          <button type="button" class="rb-dmtest" id="dm-t1">Test Stimulus</button>
          <p class="rb-dmnote" id="dm-n1"></p>
        </div>

        <div class="rb-phase" id="dm-p2" data-locked="1">
          <h3>Phase 2: Discover the Circuit Connectivity</h3>
          <div class="rb-leg">
            <span>Silent:<i class="sw" style="background:var(--gray)"></i></span>
            <span>Excitatory:<i class="sw" style="background:var(--red)"></i></span>
            <span>Inhibitory:<i class="sw" style="background:var(--blue)"></i></span>
          </div>
          <div class="rb-neuron"><svg viewBox="0 0 376 336" role="img" aria-label="Your circuit">
            <use href="#rgc-art-M"/><g class="rb-conn" id="dm-dots"></g></svg></div>
          <div class="rb-opt"><b>Threshold:</b>
            <input class="rb-num" type="number" min="0" max="9" value="1" id="dm-thr">
            <button type="button" class="rb-btn" style="flex:0 0 auto;padding:.2rem .5rem" id="dm-delays">Delays&hellip;</button></div>
          <div class="rb-opt"><b>Type:</b>
            <label class="rb-radio"><input type="radio" name="dm-pol" value="ON" checked> ON</label>
            <label class="rb-radio"><input type="radio" name="dm-pol" value="OFF"> OFF</label></div>
          <button type="button" class="rb-dmtest" id="dm-t2">Test Connectivity</button>
          <p class="rb-dmnote" id="dm-n2"></p>
        </div>
      </div>
    </div>
  </div>

  <!-- ================= Lesson Plans ================= -->
  <div class="rb-mode rb-doc" id="rb-mode-lp" hidden>
    <div class="rb-docbar">
      <h3>RetINaBox Lesson Plans</h3><div class="sp"></div>
      <a class="primary" id="lp-new" target="_blank" rel="noopener">Open in new tab</a>
      <a id="lp-gh" target="_blank" rel="noopener">View on GitHub</a>
    </div>
    <div class="rb-frame" id="lp-frame"><p class="note">Loading&hellip;</p></div>
    <p class="rb-dochint">Four lessons plus full solutions. Open it in a new tab to keep it
      beside the GUI while you work, or if it does not display here.</p>
  </div>

  <!-- ================= Teaching Slides ================= -->
  <div class="rb-mode rb-doc" id="rb-mode-sl" hidden>
    <div class="rb-docbar">
      <h3>RetINaBox Teaching Slides</h3><div class="sp"></div>
      <a class="primary" id="sl-new" target="_blank" rel="noopener">Open in new tab</a>
      <a id="sl-gh" target="_blank" rel="noopener">View on GitHub</a>
    </div>
    <div class="rb-frame" id="sl-frame"><p class="note">Loading&hellip;</p></div>
    <p class="rb-dochint">Slide deck for the four lessons. Open it in a new tab to keep it
      beside the GUI while you work, or if it does not display here.</p>
  </div>

  <!-- delay / connectivity dialog, mirrors GridPopupDialog -->
  <div class="rb-modal" id="rb-modal" hidden role="dialog" aria-modal="true" aria-labelledby="rb-modal-h">
    <div class="rb-sheet">
      <h2 id="rb-modal-h">RGC Connectivity</h2>
      <div class="rb-units" id="rb-units"></div>
      <button type="button" class="rb-close" id="rb-modal-x">Done</button>
    </div>
  </div>

  <div class="rb-foot">
    Web edition of <b>RetINaBox</b> (Trenholm Lab). Artwork and circuit model from the
    desktop application &mdash; hardware build files, lesson plans and source:
    <a href="https://github.com/Trenholm-Lab/RetINaBox">github.com/Trenholm-Lab/RetINaBox</a>.
  </div>
</div>

<script>
(function(){
"use strict";

/*===MODEL-START===*/
/* ============================================================================
   MODEL — port of GUI/gpio_manager.py (GPIOWorker) and GUI/data_manager.py

   THE ONE CHANGE FROM THE PHYSICAL BOX
   ------------------------------------
   Hardware chain:  stimulus generator -> GPIO write -> LED -> photon
                    -> photodiode -> GPIO read -> 9 channel values -> RGCs
   Here:            stimulus generator -> writeChannels() -> 9 channel values -> RGCs

   `channels` holds exactly what read_photodiodes() returned: nine values,
   1 = lit, 0 = dark, row-major. Everything downstream is unchanged, so a build
   with real hardware only needs writeChannels() swapped for a device read.
   The desktop app already fell through to this when no Pi was attached
   (read_photodiodes -> `return np.array(data_manager.activated_stim_states)`).
   ========================================================================== */
var DT_MS=25, DUR_S=10, NBUF=Math.round(DUR_S*1000/DT_MS);
var SPEED_MS=[500,300,100];
var DELAY_MS={None:0, short:100, medium:300, long:500};
var DELAY_KEYS=['None','short','medium','long'];
var STATES=['off','excitatory','inhibitory'];

function grid(v){ return [[v,v,v],[v,v,v],[v,v,v]]; }
function blankConn(){
  var a=[],r,c;
  for(r=0;r<3;r++){ a.push([]); for(c=0;c<3;c++) a[r].push({state:'off',delay:'None'}); }
  return a;
}
function createModel(){
  return {
    selected:grid(false), activated:grid(false),
    mode:'Static', speed:1, direction:'Right', running:false,
    rgc:[{polarity:'ON',threshold:1,conn:blankConn()},
         {polarity:'ON',threshold:1,conn:blankConn()}],
    channels:new Float32Array(9),
    hist:new Float32Array(NBUF*9), head:NBUF-1,
    contrib:[new Float32Array(NBUF*9), new Float32Array(NBUF*9)],
    sum:[new Float32Array(NBUF), new Float32Array(NBUF)],
    spike:[new Uint8Array(NBUF), new Uint8Array(NBUF)],
    lit:new Uint8Array(NBUF*9),
    motionAcc:0
  };
}
function clearTraces(M){
  M.hist.fill(0); M.lit.fill(0); M.head=NBUF-1; M.motionAcc=0;
  for(var k=0;k<2;k++){ M.contrib[k].fill(0); M.sum[k].fill(0); M.spike[k].fill(0); }
}
function nextCoord(r,c,dir){
  if(dir==='Up')   return [(r+2)%3,c];
  if(dir==='Down') return [(r+1)%3,c];
  if(dir==='Left') return [r,(c+2)%3];
  return [r,(c+1)%3];
}
function armStimulus(M){
  for(var r=0;r<3;r++) for(var c=0;c<3;c++)
    M.activated[r][c] = M.running ? M.selected[r][c] : false;
  M.motionAcc=0;
}
function stepMotion(M){
  var next=[],r,c,i,p;
  for(r=0;r<3;r++) for(c=0;c<3;c++) if(M.activated[r][c]){
    M.activated[r][c]=false; next.push(nextCoord(r,c,M.direction));
  }
  for(i=0;i<next.length;i++){ p=next[i]; M.activated[p[0]][p[1]]=true; }
}
function writeChannels(M){        /* replaces write_stim_leds + read_photodiodes */
  for(var r=0;r<3;r++) for(var c=0;c<3;c++)
    M.channels[r*3+c] = M.activated[r][c] ? 1 : 0;
}
function channelAt(M,back,ch){    /* = photodiode_buffer[-1-delay_steps] */
  var i=(M.head-back)%NBUF; if(i<0) i+=NBUF;
  return M.hist[i*9+ch];
}
function tick(M){
  if(M.running && M.mode==='Motion'){
    var iv=SPEED_MS[M.speed];
    M.motionAcc+=DT_MS;
    while(M.motionAcc>=iv){ stepMotion(M); M.motionAcc-=iv; }
  }
  writeChannels(M);
  M.head=(M.head+1)%NBUF;
  M.hist.set(M.channels, M.head*9);
  for(var i=0;i<9;i++) M.lit[M.head*9+i]=M.channels[i]>0.5?1:0;

  for(var k=0;k<2;k++){
    var g=M.rgc[k], s=0, base=M.head*9;
    for(var ch=0;ch<9;ch++){
      var cell=g.conn[(ch/3)|0][ch%3], x=0;
      if(cell.state!=='off'){
        var v=channelAt(M, Math.round(DELAY_MS[cell.delay]/DT_MS), ch);
        if(g.polarity==='OFF') v=1-v;
        x=(cell.state==='excitatory'?1:-1)*v;
      }
      M.contrib[k][base+ch]=x; s+=x;
    }
    M.sum[k][M.head]=s;
    M.spike[k][M.head]=(s>=g.threshold)?1:0;
  }
}
/*===MODEL-END===*/

/* ============================================================================
   PRESETS — new; the repository ships an empty custom_presets/
   ========================================================================== */
function conn(spec, d){
  d = d || '000000000';
  var a=blankConn();
  for(var ch=0;ch<9;ch++){
    var s=spec[ch];
    var st = s==='e'?'excitatory' : s==='i'?'inhibitory' : 'off';
    /* ConnectivityUnit.update_state: a silent input carries no delay */
    a[(ch/3)|0][ch%3]={ state:st, delay: st==='off' ? 'None' : DELAY_KEYS[+d[ch]] };
  }
  return a;
}
var PRESETS=[
  {id:'on-center', name:'ON cell', apply:function(M){
    M.rgc[0]={polarity:'ON',threshold:1,conn:conn('....e....')};
    M.rgc[1]={polarity:'ON',threshold:1,conn:blankConn()};
    M.selected=grid(false); M.selected[1][1]=true; M.mode='Static';
  }},
  {id:'off-center', name:'OFF cell', apply:function(M){
    M.rgc[0]={polarity:'OFF',threshold:1,conn:conn('....e....')};
    M.rgc[1]={polarity:'ON',threshold:1,conn:blankConn()};
    M.selected=grid(false); M.selected[1][1]=true; M.mode='Static';
  }},
  {id:'parallel', name:'ON and OFF in parallel', apply:function(M){
    M.rgc[0]={polarity:'ON', threshold:1,conn:conn('....e....')};
    M.rgc[1]={polarity:'OFF',threshold:1,conn:conn('....e....')};
    M.selected=grid(false); M.selected[1][1]=true; M.mode='Static';
  }},
  {id:'center-surround', name:'Centre\u2013surround', apply:function(M){
    M.rgc[0]={polarity:'ON',threshold:1,conn:conn('iiiieiiii')};
    M.rgc[1]={polarity:'ON',threshold:1,conn:blankConn()};
    M.selected=grid(false); M.selected[1][1]=true; M.mode='Static';
  }},
  {id:'center-surround-sizes', name:'Centre\u2013surround, small and large', apply:function(M){
    /* Lesson 1 Activity 4: same centre, different spot-size preference.
       RGC1 takes the single centre lamp; RGC2 takes lamps 2,4,5,6,8. */
    M.rgc[0]={polarity:'ON',threshold:1,conn:conn('iiiieiiii')};
    M.rgc[1]={polarity:'ON',threshold:5,conn:conn('ieieeeiei')};
    M.selected=grid(false); M.selected[1][1]=true; M.mode='Static';
  }},
  {id:'direction-selective', name:'Direction-selective cell', apply:function(M){
    /* excitation from the middle column, inhibition from the left column
       arriving 300 ms later = one stimulus step at Medium (Barlow\u2013Levick) */
    M.rgc[0]={polarity:'ON',threshold:1,conn:conn('ie.ie.ie.','202202202')};
    M.rgc[1]={polarity:'ON',threshold:1,conn:blankConn()};
    M.selected=grid(false);
    M.selected[0][0]=M.selected[1][0]=M.selected[2][0]=true;
    M.mode='Motion'; M.speed=1; M.direction='Right';
  }},
  {id:'ds-pair', name:'Direction-selective pair (left and right)', apply:function(M){
    /* Lesson 3 Activities 1-2, and the Block Breaker setup: RGC1 prefers
       leftward motion, RGC2 prefers rightward. Mirror-image wiring. */
    M.rgc[0]={polarity:'ON',threshold:6,conn:conn('ieeieeiee','202202202')};
    M.rgc[1]={polarity:'ON',threshold:6,conn:conn('eeieeieei','202202202')};
    M.selected=grid(false);
    M.selected[0][0]=M.selected[1][0]=M.selected[2][0]=true;
    M.mode='Motion'; M.speed=1; M.direction='Right';
  }}
];

/* ============================================================================
   VIEW
   ========================================================================== */
var COL={red:'#CD1916',blue:'#1A83C9',yellow:'#DEB33D',green:'#3D783F',
         gray:'#BDBFB6',lightGray:'#E0E0E0',black:'#000000',line:'#CCCCCC'};
/* The desktop app crossed these: RGC_1.svg is green but graphing_manager.py
   gave RGC 1 the yellow trace. Traces now follow the somas. */
var RGC_TRACE=[COL.green, COL.yellow];

/* interaction_manager.py :: NeuronWidget.circle_positions, in the SVG's own
   376x336 coordinate space, with radius min(35,35)/3 */
var DOTS=[[12,38],[127,38],[241,38],[65,105],[179,105],[295,105],
          [120,172],[239,172],[353,172]];
var DOT_R=35/3;

var M=createModel();
var root=document.getElementById('rb');
var elLamps=document.getElementById('rb-lamps');
var elNeurons=document.getElementById('rb-neurons');
var elRun=document.getElementById('rb-run');
var canvas=document.getElementById('rb-canvas');
var ctx=canvas.getContext('2d');
var lampUses=[], dotEls=[[],[]];

/* ---------- stimulus lamps ---------- */
(function(){
  for(var r=0;r<3;r++) for(var c=0;c<3;c++){
    var b=document.createElement('button');
    b.type='button'; b.className='rb-lamp';
    b.setAttribute('aria-pressed','false');
    b.setAttribute('aria-label','LED '+(r*3+c+1));
    b.innerHTML='<svg viewBox="0 0 88 104"><use href="#led-unselected"/></svg><b>'+(r*3+c+1)+'</b>';
    (function(r,c){
      b.addEventListener('click',function(){
        M.selected[r][c]=!M.selected[r][c];
        if(M.running) armStimulus(M);
        syncStim();
      });
    })(r,c);
    elLamps.appendChild(b);
    lampUses.push(b.querySelector('use'));
  }
})();

/* ---------- neuron widgets ---------- */
(function(){
  for(var k=0;k<2;k++){
    var wrap=document.createElement('div');

    var art='<div class="rb-neuron"><svg viewBox="0 0 376 336" role="img" aria-label="RGC '+(k+1)+
            ' dendritic field">'+
            '<use href="#rgc-art-'+(k+1)+'"/><g class="rb-conn"></g></svg></div>';

    var ctrl=
      '<div class="rb-opt"><b>Threshold:</b>'+
        '<input class="rb-num" type="number" min="0" max="9" step="1" value="1" id="rb-thr-'+k+'">'+
        '<button type="button" class="rb-btn" style="flex:0 0 auto;padding:.2rem .5rem" '+
          'id="rb-delays-'+k+'">Delays\u2026</button></div>'+
      '<div class="rb-opt"><b>Type:</b>'+
        '<label class="rb-radio"><input type="radio" name="rb-pol-'+k+'" value="ON" checked> ON</label>'+
        '<label class="rb-radio"><input type="radio" name="rb-pol-'+k+'" value="OFF"> OFF</label></div>';

    wrap.innerHTML = art + ctrl + (k===0 ? '<hr class="rb-sep">' : '');
    elNeurons.appendChild(wrap);

    /* connectivity dots, drawn over the artwork exactly as paintEvent does */
    var g=wrap.querySelector('.rb-conn'), ns='http://www.w3.org/2000/svg';
    for(var ch=0;ch<9;ch++){
      var grp=document.createElementNS(ns,'g');
      grp.setAttribute('class','rb-dot');
      grp.setAttribute('tabindex','0');
      grp.setAttribute('role','button');
      var ci=document.createElementNS(ns,'circle');
      ci.setAttribute('class','rb-dot-c');
      ci.setAttribute('cx',DOTS[ch][0]); ci.setAttribute('cy',DOTS[ch][1]);
      ci.setAttribute('r',DOT_R); ci.setAttribute('fill',COL.gray);
      var tri=document.createElementNS(ns,'path');
      tri.setAttribute('class','rb-dot-t');
      tri.setAttribute('d','M'+DOTS[ch][0]+' '+(DOTS[ch][1]-6)+
                        'l6.5 11h-13z');
      tri.setAttribute('fill',COL.black);
      grp.appendChild(ci); grp.appendChild(tri);
      (function(k,ch,grp){
        function cycle(){
          var cell=M.rgc[k].conn[(ch/3)|0][ch%3];
          cell.state=STATES[(STATES.indexOf(cell.state)+1)%3];
          if(cell.state==='off') cell.delay='None';   /* ConnectivityUnit.update_state */
          syncNeurons();
        }
        grp.addEventListener('click',cycle);
        grp.addEventListener('keydown',function(e){
          if(e.key==='Enter'||e.key===' '){ e.preventDefault(); cycle(); }
        });
      })(k,ch,grp);
      g.appendChild(grp); dotEls[k].push(grp);
    }

    (function(k,wrap){
      wrap.querySelector('#rb-thr-'+k).addEventListener('change',function(e){
        var v=Math.max(0,Math.min(9,Math.round(+e.target.value||0)));
        e.target.value=v; M.rgc[k].threshold=v;
      });
      [].forEach.call(wrap.querySelectorAll('input[name="rb-pol-'+k+'"]'),function(r){
        r.addEventListener('change',function(){ if(r.checked) M.rgc[k].polarity=r.value; });
      });
      wrap.querySelector('#rb-delays-'+k).addEventListener('click',function(){ openModal(k); });
    })(k,wrap);
  }
})();

/* ---------- connectivity dialog (GridPopupDialog + ConnectivityUnit) ---------- */
var modal=document.getElementById('rb-modal'), units=document.getElementById('rb-units');
function openModal(k){
  openModalFor('RGC '+(k+1), M.rgc[k].conn, syncNeurons);
}
function openModalFor(title, connObj, onChange){
  document.getElementById('rb-modal-h').textContent=title+' Connectivity';
  units.innerHTML='';
  for(var ch=0;ch<9;ch++){
    var cell=connObj[(ch/3)|0][ch%3];
    var u=document.createElement('div'); u.className='rb-unit';
    u.innerHTML=
      '<button type="button" class="rb-pm" data-state="'+cell.state+'">'+
        (cell.state==='excitatory'?'+':cell.state==='inhibitory'?'\u2212':'')+'</button>'+
      '<label>Delay</label>'+
      '<input type="range" min="0" max="3" step="1" value="'+DELAY_KEYS.indexOf(cell.delay)+'"'+
        (cell.state==='off'?' disabled':'')+'>'+
      '<small>'+DELAY_MS[cell.delay]+' ms</small>';
    (function(ch,u){
      var cellRef=connObj[(ch/3)|0][ch%3];
      var btn=u.querySelector('.rb-pm'), sl=u.querySelector('input'), lab=u.querySelector('small');
      btn.addEventListener('click',function(){
        cellRef.state=STATES[(STATES.indexOf(cellRef.state)+1)%3];
        btn.dataset.state=cellRef.state;
        btn.textContent=cellRef.state==='excitatory'?'+':cellRef.state==='inhibitory'?'\u2212':'';
        if(cellRef.state==='off'){ cellRef.delay='None'; sl.value=0; sl.disabled=true; }
        else sl.disabled=false;
        lab.textContent=DELAY_MS[cellRef.delay]+' ms';
        onChange();
      });
      sl.addEventListener('input',function(){
        cellRef.delay=DELAY_KEYS[+sl.value];
        lab.textContent=DELAY_MS[cellRef.delay]+' ms';
        onChange();
      });
    })(ch,u);
    units.appendChild(u);
  }
  modal.hidden=false;
}
document.getElementById('rb-modal-x').addEventListener('click',function(){ modal.hidden=true; });
modal.addEventListener('click',function(e){ if(e.target===modal) modal.hidden=true; });
document.addEventListener('keydown',function(e){ if(e.key==='Escape') modal.hidden=true; });

/* ---------- presets ---------- */
(function(){
  var sel=document.getElementById('rb-preset');
  PRESETS.forEach(function(p){
    var o=document.createElement('option'); o.value=p.id; o.textContent=p.name; sel.appendChild(o);
  });
  /* the dropdown only chooses; the button applies it */
  document.getElementById('rb-load').addEventListener('click',function(){
    if(sel.value) loadPreset(sel.value);
  });
})();
function loadPreset(id){
  var p=null; PRESETS.forEach(function(q){ if(q.id===id) p=q; });
  if(!p) return false;
  p.apply(M); M.running=true; armStimulus(M); clearTraces(M);
  document.getElementById('rb-preset').value=id;
  syncAll(); return true;
}

/* ---------- control wiring ---------- */
[].forEach.call(document.querySelectorAll('input[name="rb-mode"]'),function(r){
  r.addEventListener('change',function(){
    if(!r.checked) return;
    M.mode=r.value; if(M.running) armStimulus(M); syncStim();
  });
});
[].forEach.call(document.querySelectorAll('input[name="rb-dir"]'),function(r){
  r.addEventListener('change',function(){ if(r.checked){ M.direction=r.value; syncStim(); } });
});
document.getElementById('rb-speed').addEventListener('input',function(e){
  M.speed=+e.target.value; syncStim();
});
document.getElementById('rb-all').addEventListener('click',function(){
  M.selected=grid(true); if(M.running) armStimulus(M); syncStim();
});
document.getElementById('rb-none').addEventListener('click',function(){
  M.selected=grid(false); if(M.running) armStimulus(M); syncStim();
});
elRun.addEventListener('click',function(){
  M.running=!M.running; armStimulus(M); syncStim();
});

/* ---------- sync ---------- */
var SPEED_NAME=['Slow','Medium','Fast'];
function syncStim(){
  document.getElementById('rb-dir-row').hidden   = (M.mode!=='Motion');
  document.getElementById('rb-speed-row').hidden = (M.mode!=='Motion');
  document.getElementById('rb-speed-lbl').textContent=SPEED_NAME[M.speed];
  document.getElementById('rb-speed').value=M.speed;
  elRun.textContent = M.running ? 'Deactivate stimulus LEDs' : 'Activate stimulus LEDs';
  elRun.classList.toggle('is-on', M.running);
  [].forEach.call(document.querySelectorAll('input[name="rb-mode"]'),function(r){
    r.checked=(r.value===M.mode); });
  [].forEach.call(document.querySelectorAll('input[name="rb-dir"]'),function(r){
    r.checked=(r.value===M.direction); });
  for(var r2=0;r2<3;r2++) for(var c=0;c<3;c++)
    elLamps.children[r2*3+c].setAttribute('aria-pressed',String(M.selected[r2][c]));
}
function syncNeurons(){
  for(var k=0;k<2;k++){
    for(var ch=0;ch<9;ch++){
      var cell=M.rgc[k].conn[(ch/3)|0][ch%3], grp=dotEls[k][ch];
      grp.querySelector('.rb-dot-c').setAttribute('fill',
        cell.state==='excitatory'?COL.red : cell.state==='inhibitory'?COL.blue : COL.gray);
      grp.querySelector('.rb-dot-t').style.display = (cell.delay!=='None') ? '' : 'none';
      grp.setAttribute('aria-label','Input '+(ch+1)+': '+cell.state+
        ', delay '+DELAY_MS[cell.delay]+' ms');
    }
    root.querySelector('#rb-thr-'+k).value=M.rgc[k].threshold;
    [].forEach.call(root.querySelectorAll('input[name="rb-pol-'+k+'"]'),function(r){
      r.checked=(r.value===M.rgc[k].polarity); });
  }
}
function syncAll(){ syncStim(); syncNeurons(); }

/* ---------- live lamp state ---------- */
function paintLamps(){
  for(var r=0;r<3;r++) for(var c=0;c<3;c++){
    var i=r*3+c;
    var href = M.activated[r][c] ? '#led-on'
             : M.selected[r][c]  ? '#led-selected' : '#led-unselected';
    if(lampUses[i].getAttribute('href')!==href) lampUses[i].setAttribute('href',href);
  }
}

/* ============================================================================
   SIGNAL MONITOR
   Mirrors graphing_manager.py: each photoreceptor is a horizontal trace at a
   fixed height, grey by default, red while it drives the cell and blue while it
   inhibits it. Input lamps on the right, RGC output row beneath, 1 s scale bar.
   ========================================================================== */
var ROW=13, RGC_GAP=14, RGC_ROW=15, AX=44, TITLE=18, PAD=8;
var LEFT=64, RIGHT=74;
var BLOCK=TITLE+9*ROW+RGC_GAP+RGC_ROW+AX;
var CH=PAD+BLOCK*2+PAD, CW=600, dpr=1, FONT='10px sans-serif';

function resize(){
  var w=canvas.parentNode.clientWidth; if(w<300) w=300;
  CW=w; dpr=Math.min(window.devicePixelRatio||1,2);
  canvas.width=Math.round(CW*dpr); canvas.height=Math.round(CH*dpr);
  canvas.style.height=CH+'px';
  FONT='10px '+getComputedStyle(root).fontFamily;
  ctx.setTransform(dpr,0,0,dpr,0,0);
}
window.addEventListener('resize',resize);

function drawRGC(k,top){
  var w=CW-LEFT-RIGHT, i, j, y;
  ctx.font=FONT; ctx.textBaseline='middle';

  ctx.textAlign='center'; ctx.fillStyle='#333';
  ctx.fillText('RGC '+(k+1), LEFT+w/2, top+8);

  var plotTop=top+TITLE;

  /* nine photoreceptor traces */
  for(j=0;j<9;j++){
    y=plotTop+j*ROW+ROW/2;
    ctx.textAlign='right'; ctx.fillStyle='#555';
    ctx.fillText(String(j+1), LEFT-6, y);

    ctx.strokeStyle=COL.gray; ctx.lineWidth=2;
    ctx.beginPath(); ctx.moveTo(LEFT,y); ctx.lineTo(LEFT+w,y); ctx.stroke();

    for(var pass=0;pass<2;pass++){
      ctx.strokeStyle=pass?COL.blue:COL.red; ctx.lineWidth=3;
      ctx.beginPath();
      var run=false;
      for(i=0;i<NBUF;i++){
        var v=M.contrib[k][(((M.head+1+i)%NBUF)*9)+j];
        var hit=pass?(v<-0.5):(v>0.5);
        var x=LEFT+(i/(NBUF-1))*w;
        if(hit&&!run){ ctx.moveTo(x,y); run=true; }
        else if(hit){ ctx.lineTo(x,y); }
        else run=false;
      }
      ctx.stroke();
    }

    /* photoreceptor input lamp */
    var lit=M.lit[M.head*9+j]===1;
    ctx.beginPath(); ctx.arc(LEFT+w+12,y,4.5,0,6.2832);
    ctx.fillStyle=lit?'#FDFF6E':'#fff'; ctx.fill();
    ctx.strokeStyle='#666'; ctx.lineWidth=1; ctx.stroke();
  }

  /* rotated axis captions */
  ctx.save();
  ctx.translate(14, plotTop+9*ROW/2); ctx.rotate(-Math.PI/2);
  ctx.textAlign='center'; ctx.fillStyle='#555';
  ctx.fillText('Photoreceptor Output', 0, 0);
  ctx.restore();
  ctx.save();
  ctx.translate(CW-10, plotTop+9*ROW/2); ctx.rotate(-Math.PI/2);
  ctx.textAlign='center'; ctx.fillStyle='#555';
  ctx.fillText('Photoreceptor Input', 0, 0);
  ctx.restore();

  /* RGC output row */
  var ry=plotTop+9*ROW+RGC_GAP+RGC_ROW/2;
  ctx.textAlign='right'; ctx.fillStyle='#555';
  ctx.fillText('RGC '+(k+1), LEFT-6, ry);
  ctx.strokeStyle=COL.gray; ctx.lineWidth=2;
  ctx.beginPath(); ctx.moveTo(LEFT,ry); ctx.lineTo(LEFT+w,ry); ctx.stroke();
  ctx.strokeStyle=RGC_TRACE[k]; ctx.lineWidth=4;
  ctx.beginPath();
  var run2=false;
  for(i=0;i<NBUF;i++){
    var sp=M.spike[k][(M.head+1+i)%NBUF];
    var x2=LEFT+(i/(NBUF-1))*w;
    if(sp&&!run2){ ctx.moveTo(x2,ry); run2=true; }
    else if(sp){ ctx.lineTo(x2,ry); }
    else run2=false;
  }
  ctx.stroke();

  /* time axis with 1 s scale bar */
  var ay=ry+RGC_ROW/2+9;
  ctx.strokeStyle='#999'; ctx.lineWidth=1;
  ctx.beginPath(); ctx.moveTo(LEFT,ay+.5); ctx.lineTo(LEFT+w,ay+.5); ctx.stroke();
  for(i=0;i<=DUR_S*2;i++){
    var tx=LEFT+(i/(DUR_S*2))*w;
    ctx.beginPath(); ctx.moveTo(tx+.5,ay); ctx.lineTo(tx+.5,ay+(i%2?3:5)); ctx.stroke();
  }
  ctx.fillStyle='#555'; ctx.textAlign='center';
  ctx.fillText('Time', LEFT+w/2, ay+15);

  var sb=w/DUR_S, sx=LEFT+w-sb;
  ctx.strokeStyle='#333'; ctx.lineWidth=2;
  ctx.beginPath(); ctx.moveTo(sx,ay+13); ctx.lineTo(LEFT+w,ay+13); ctx.stroke();
  ctx.fillStyle='#333'; ctx.textAlign='center';
  ctx.fillText('1 sec', sx+sb/2, ay+21);
}

function draw(){
  ctx.clearRect(0,0,CW,CH);
  drawRGC(0,PAD);
  drawRGC(1,PAD+BLOCK);
}

/* ---------- clock: fixed 25 ms steps ---------- */
var last=0, acc=0;
function frame(now){
  if(!last) last=now;
  acc+=now-last; last=now;
  if(acc>500) acc=500;
  while(acc>=DT_MS){ tick(M); tick(DM.model); acc-=DT_MS; }
  if(currentMode==='lab'){ paintLamps(); draw(); }
  else if(currentMode==='dm'){ dmDraw(); }
  requestAnimationFrame(frame);
}


