var CB_DATA = CB_DEFAULT, DM_DATA = DM_DEFAULT;

/* ============================================================================
   TABS
   ========================================================================== */
/* ---------------------------------------------------------------------------
   Reference documents. raw.githubusercontent.com cannot be framed -- it returns
   x-frame-options: deny, a sandbox CSP and content-type application/octet-stream
   -- so the PDFs are pulled through jsDelivr, which serves the same repo files
   with a real application/pdf type and no frame blocking. Some browsers (notably
   iOS) never render PDFs inline, hence the always-visible "Open in new tab".
   --------------------------------------------------------------------------- */
var REPO='Trenholm-Lab/RetINaBox', BRANCH='main';
var DOCS={
  lp:{file:'Lesson Plans/RetINaBox_LessonPlans.pdf',   frame:'lp-frame', a:'lp-new', gh:'lp-gh'},
  sl:{file:'Lesson Plans/RetINaBox_TeachingSlides.pdf',frame:'sl-frame', a:'sl-new', gh:'sl-gh'}
};
function cdnURL(f){
  return 'https://cdn.jsdelivr.net/gh/'+REPO+'@'+BRANCH+'/'+
         f.split('/').map(encodeURIComponent).join('/');
}
function ghURL(f){
  return 'https://github.com/'+REPO+'/blob/'+BRANCH+'/'+
         f.split('/').map(encodeURIComponent).join('/');
}
function mountDoc(key){
  var d=DOCS[key], box=document.getElementById(d.frame);
  document.getElementById(d.a).href  = d.url || cdnURL(d.file);
  document.getElementById(d.gh).href = d.gh_url || ghURL(d.file);
  if(box.dataset.mounted) return;
  box.dataset.mounted='1';

  var note=box.querySelector('.note'), settled=false;
  var f=document.createElement('iframe');
  f.title=(key==='lp'?'RetINaBox lesson plans':'RetINaBox teaching slides');

  /* the frame paints over the overlay, so the overlay has to be taken out
     once the document is up -- otherwise it sits on top of the PDF forever */
  var giveUp=setTimeout(function(){
    if(settled || !note) return;
    note.textContent='This browser may not show PDFs inline. Use "Open in new tab".';
  }, 8000);
  f.addEventListener('load', function(){
    settled=true; clearTimeout(giveUp);
    if(note && note.parentNode) note.parentNode.removeChild(note);
  });

  f.src=(d.url || cdnURL(d.file))+'#view=FitH';
  box.appendChild(f);
}

var currentMode='lab';
[].forEach.call(document.querySelectorAll('.rb-tab'),function(t){
  t.addEventListener('click',function(){
    currentMode=t.dataset.mode;
    [].forEach.call(document.querySelectorAll('.rb-tab'),function(o){
      o.setAttribute('aria-selected', String(o===t)); });
    ['lab','cb','dm','lp','sl'].forEach(function(m){
      document.getElementById('rb-mode-'+m).hidden = (m!==currentMode); });
    if(currentMode==='dm'){ dmResize(); }
    if(currentMode==='lab'){ resize(); }
    if(currentMode==='lp'||currentMode==='sl'){ mountDoc(currentMode); }
  });
});

/* ============================================================================
   CODE BREAKER  (code_breaker.py)
   ========================================================================== */
function pat3(arr, cls){
  var h='<div class="pat">';
  for(var i=0;i<9;i++) h+='<i class="'+(arr[i]?'on':'')+'"></i>';
  return h+'</div>';
}
/* parse_solution_string: longest tokens first, so multi-character letters win */
function cbTokens(str, letters){
  var sorted=letters.slice().sort(function(a,b){return b.length-a.length;});
  var out=[], i=0;
  while(i<str.length){
    if(str[i]===' '){ out.push(' '); i++; continue; }
    var matched=false;
    for(var j=0;j<sorted.length;j++){
      var L=sorted[j];
      if(L.length>1 && str.substr(i,L.length).toUpperCase()===L.toUpperCase()){
        out.push(L.toUpperCase()); i+=L.length; matched=true; break;
      }
    }
    if(!matched){
      var up=str[i].toUpperCase();
      out.push(letters.some(function(L){return L.toUpperCase()===up;}) ? up : str[i]);
      i++;
    }
  }
  return out;
}
var cbSel=document.getElementById('cb-sel');
function cbBuildMenu(){
  cbSel.innerHTML='';
  Object.keys(CB_DATA).forEach(function(k){
    var o=document.createElement('option'); o.value=k; o.textContent=k; cbSel.appendChild(o);
  });
}
function cbLoad(name){
  var d=CB_DATA[name]; if(!d) return;
  var letters=d.RetinaBox_output;
  var pool=JSON.parse(JSON.stringify(d.stim_codes));
  var toks=cbTokens(d.Solution_string, letters);
  var code=document.getElementById('cb-code'); code.innerHTML='';
  toks.forEach(function(tk){
    var el=document.createElement('div');
    var isLetter=letters.some(function(L){return L.toUpperCase()===tk.toUpperCase();});
    if(tk===' '){ el.className='rb-tok sp'; el.innerHTML='&nbsp;'; }
    else if(isLetter){
      var up=tk.toUpperCase();
      var arr=(pool[up]&&pool[up].length)?pool[up].shift():[0,0,0,0,0,0,0,0,0];
      el.className='rb-tok'; el.dataset.answer=up;
      var opts='<option value=""></option>'+letters.map(function(L){
        return '<option>'+L+'</option>'; }).join('');
      el.innerHTML=pat3(arr)+'<select aria-label="Letter for this pattern">'+opts+'</select>';
    } else { el.className='rb-tok'; el.innerHTML='<b>'+tk+'</b>'; }
    code.appendChild(el);
  });
  var pref=document.getElementById('cb-pref');
  pref.innerHTML='<figure>'+pat3(d.RGC_1_pref_stim)+'RGC 1</figure>'+
                 '<figure>'+pat3(d.RGC_2_pref_stim)+'RGC 2</figure>';
  var rows=[['0','0',letters[0]],['1','0',letters[1]],['0','1',letters[2]],['1','1',letters[3]]];
  document.getElementById('cb-book').innerHTML=rows.map(function(r){
    return '<tr><td>'+r[0]+'</td><td>'+r[1]+'</td><td>'+r[2]+'</td></tr>'; }).join('');
  document.getElementById('cb-result').textContent='';
}
cbSel.addEventListener('change',function(){ cbLoad(cbSel.value); });
document.getElementById('cb-check').addEventListener('click',function(){
  var toks=document.querySelectorAll('#cb-code .rb-tok[data-answer]');
  var right=0;
  [].forEach.call(toks,function(el){
    var sel=el.querySelector('select'), ok=(sel.value===el.dataset.answer);
    sel.className = sel.value ? (ok?'ok':'no') : '';
    if(ok) right++;
  });
  var res=document.getElementById('cb-result');
  res.textContent='Correct letters: '+right+' / '+toks.length;
  res.className='rb-result '+(right===toks.length?'rb-ok':'rb-no');
});

/* ============================================================================
   DISCOVERY MODE  (discovery_mode.py)
   ========================================================================== */
var DM = {
  model:createModel(), challenge:null, points:100, t0:0, timer:null,
  stim:[0,0,0,0,0,0,0,0,0], user:blankConn(), dots:[]
};
var dmSel=document.getElementById('dm-sel');
function dmBuildMenu(){
  dmSel.innerHTML='';
  Object.keys(DM_DATA).forEach(function(k){
    var o=document.createElement('option'); o.value=k; o.textContent=k; dmSel.appendChild(o);
  });
}
function dmDifficulty(n){
  return /^Easy/.test(n)?'easy' : /^Hard/.test(n)?'hard' : 'medium';
}
/* discovery_mode.py: 5 points for every difficulty */
function dmDeduction(){ return 5; }

/* Phase 1 grid */
(function(){
  var g=document.getElementById('dm-grid');
  for(var i=0;i<9;i++){
    var b=document.createElement('button');
    b.type='button'; b.textContent=String(i+1); b.setAttribute('aria-pressed','false');
    (function(i,b){
      b.addEventListener('click',function(){
        DM.stim[i]=DM.stim[i]?0:1;
        b.setAttribute('aria-pressed',String(!!DM.stim[i]));
        dmApplyStim();
      });
    })(i,b);
    g.appendChild(b);
  }
})();
/* Phase 2 dots over RGC_M */
(function(){
  var g=document.getElementById('dm-dots'), ns='http://www.w3.org/2000/svg';
  for(var ch=0;ch<9;ch++){
    var grp=document.createElementNS(ns,'g');
    grp.setAttribute('class','rb-dot'); grp.setAttribute('tabindex','0'); grp.setAttribute('role','button');
    var ci=document.createElementNS(ns,'circle');
    ci.setAttribute('class','rb-dot-c');
    ci.setAttribute('cx',DOTS[ch][0]); ci.setAttribute('cy',DOTS[ch][1]);
    ci.setAttribute('r',DOT_R); ci.setAttribute('fill',COL.gray);
    var tri=document.createElementNS(ns,'path');
    tri.setAttribute('class','rb-dot-t');
    tri.setAttribute('d','M'+DOTS[ch][0]+' '+(DOTS[ch][1]-6)+'l6.5 11h-13z');
    tri.setAttribute('fill',COL.black); tri.style.display='none';
    grp.appendChild(ci); grp.appendChild(tri);
    (function(ch,grp){
      function cycle(){
        var c=DM.user[(ch/3)|0][ch%3];
        c.state=STATES[(STATES.indexOf(c.state)+1)%3];
        if(c.state==='off') c.delay='None';
        dmSyncDots();
      }
      grp.addEventListener('click',cycle);
      grp.addEventListener('keydown',function(e){
        if(e.key==='Enter'||e.key===' '){ e.preventDefault(); cycle(); } });
    })(ch,grp);
    g.appendChild(grp); DM.dots.push(grp);
  }
})();
function dmSyncDots(){
  for(var ch=0;ch<9;ch++){
    var c=DM.user[(ch/3)|0][ch%3], grp=DM.dots[ch];
    grp.querySelector('.rb-dot-c').setAttribute('fill',
      c.state==='excitatory'?COL.red : c.state==='inhibitory'?COL.blue : COL.gray);
    grp.querySelector('.rb-dot-t').style.display=(c.delay!=='None')?'':'none';
  }
}
document.getElementById('dm-delays').addEventListener('click',function(){
  openModalFor('Your circuit', DM.user, dmSyncDots);
});

/* motion controls mirror on_motion_type_changed */
var dmMotion=document.getElementById('dm-motion'),
    dmSpeed=document.getElementById('dm-speed'),
    dmDir=document.getElementById('dm-dir');
function fill(sel,items){ sel.innerHTML=items.map(function(i){return '<option>'+i+'</option>';}).join(''); }
dmMotion.addEventListener('change',function(){
  if(dmMotion.value==='Static'){
    fill(dmSpeed,['---']); fill(dmDir,['---']);
    dmSpeed.disabled=dmDir.disabled=true;
  } else {
    fill(dmSpeed,['Slow','Medium','Fast']); dmSpeed.value='Slow';
    fill(dmDir,['Left','Right']); dmDir.value='Right';
    dmSpeed.disabled=dmDir.disabled=false;
  }
  dmApplyStim();
});
dmSpeed.addEventListener('change',dmApplyStim);
dmDir.addEventListener('change',dmApplyStim);

/* The student's own stimulus drives the hidden cell, so the live trace is a
   real probe. (The desktop app held all LEDs on in experiment mode.) */
function dmApplyStim(){
  var M2=DM.model;
  for(var r=0;r<3;r++) for(var c=0;c<3;c++) M2.selected[r][c]=!!DM.stim[r*3+c];
  M2.mode = (dmMotion.value==='Moving') ? 'Motion' : 'Static';
  M2.speed = {Slow:0,Medium:1,Fast:2}[dmSpeed.value] || 0;
  M2.direction = (dmDir.value==='Left'||dmDir.value==='Right') ? dmDir.value : 'Right';
  M2.running = !!DM.challenge;
  armStimulus(M2);
}
function dmSolutions(name){
  var d=DM_DATA[name];
  return Object.prototype.toString.call(d)==='[object Array]' ? d : [d];
}
function dmLoadHidden(name){
  var sol=dmSolutions(name)[0], M2=DM.model;
  var flat=sol.connectivity, cn=blankConn();
  for(var ch=0;ch<9;ch++) cn[(ch/3)|0][ch%3]={state:flat[ch].state, delay:flat[ch].delay};
  M2.rgc[0]={polarity:sol.polarity||'ON', threshold:sol.threshold, conn:cn};
  M2.rgc[1]={polarity:'ON', threshold:1, conn:blankConn()};
  clearTraces(M2);
}
document.getElementById('dm-start').addEventListener('click',function(){
  DM.challenge=dmSel.value;
  dmLoadHidden(DM.challenge);
  dmApplyStim();
  document.getElementById('dm-p1').dataset.locked='0';
  document.getElementById('dm-p2').dataset.locked='1';
  document.getElementById('dm-n1').textContent='';
  document.getElementById('dm-n2').textContent='';
  this.disabled=true; this.textContent='Challenge Running';
  DM.t0=Date.now();
  if(DM.timer) clearInterval(DM.timer);
  DM.timer=setInterval(function(){
    var e=Math.floor((Date.now()-DM.t0)/1000);
    document.getElementById('dm-timer').textContent=
      String(Math.floor(e/60)).padStart(2,'0')+':'+String(e%60).padStart(2,'0');
  },250);
});
dmSel.addEventListener('change',function(){
  DM.challenge=null;
  if(DM.timer){ clearInterval(DM.timer); DM.timer=null; }
  document.getElementById('dm-timer').textContent='00:00';
  document.getElementById('dm-p1').dataset.locked='1';
  document.getElementById('dm-p2').dataset.locked='1';
  var b=document.getElementById('dm-start'); b.disabled=false; b.textContent='Start Challenge';
  DM.stim=[0,0,0,0,0,0,0,0,0];
  [].forEach.call(document.querySelectorAll('#dm-grid button'),function(x){
    x.setAttribute('aria-pressed','false'); });
  DM.user=blankConn(); dmSyncDots();
  dmMotion.value='Static'; fill(dmSpeed,['---']); fill(dmDir,['---']);
  dmSpeed.disabled=dmDir.disabled=true;
  document.getElementById('dm-n1').textContent='';
  document.getElementById('dm-n2').textContent='';
  clearTraces(DM.model); dmApplyStim();
});
function dmLose(note){
  DM.points=Math.max(0, DM.points-dmDeduction());
  document.getElementById('dm-points').textContent=DM.points;
  note.textContent='Not yet — you lost '+dmDeduction()+' points. Try again.';
  note.className='rb-dmnote rb-no';
}
document.getElementById('dm-t1').addEventListener('click',function(){
  var note=document.getElementById('dm-n1');
  if(!DM.challenge) return;
  if(DM.stim.every(function(v){return !v;})){
    note.textContent='Select at least one stimulus position.'; note.className='rb-dmnote'; return;
  }
  var uMot=dmMotion.value.toLowerCase(), uSpd=dmSpeed.value.toLowerCase(), uDir=dmDir.value.toLowerCase();
  var hit=dmSolutions(DM.challenge).some(function(k){
    var kd=k.direction===''?'---':k.direction.toLowerCase();
    var ks=k.speed===''?'---':k.speed.toLowerCase();
    return k.stim_array.every(function(v,i){return !!v===!!DM.stim[i];}) &&
           k.motion_type.toLowerCase()===uMot && kd===uDir && ks===uSpd;
  });
  if(hit){
    note.textContent='Correct stimulus. Proceed to Phase 2.'; note.className='rb-dmnote rb-ok';
    document.getElementById('dm-p1').dataset.locked='1';
    document.getElementById('dm-p2').dataset.locked='0';
  } else dmLose(note);
});
document.getElementById('dm-t2').addEventListener('click',function(){
  var note=document.getElementById('dm-n2');
  if(!DM.challenge) return;
  var flat=[];
  for(var ch=0;ch<9;ch++) flat.push(DM.user[(ch/3)|0][ch%3]);
  if(flat.every(function(c){return c.state==='off';})){
    note.textContent='Configure at least one photoreceptor.'; note.className='rb-dmnote'; return;
  }
  var uThr=+document.getElementById('dm-thr').value;
  var uPol=document.querySelector('input[name="dm-pol"]:checked').value;
  var uMot=dmMotion.value.toLowerCase(), uSpd=dmSpeed.value.toLowerCase(),
      uDir=dmDir.value.toLowerCase();
  var hit=dmSolutions(DM.challenge).some(function(k){
    var kd=k.direction===''?'---':k.direction.toLowerCase();
    var ks=k.speed===''?'---':k.speed.toLowerCase();
    return k.connectivity.every(function(c,i){
             return c.state===flat[i].state && c.delay===flat[i].delay; }) &&
           k.threshold===uThr && (k.polarity||'ON')===uPol &&
           k.stim_array.every(function(v,i){return !!v===!!DM.stim[i];}) &&
           k.motion_type.toLowerCase()===uMot && kd===uDir && ks===uSpd;
  });
  if(hit){
    note.textContent='Correct connectivity. Challenge completed.'; note.className='rb-dmnote rb-ok';
    document.getElementById('dm-p2').dataset.locked='1';
    if(DM.timer){ clearInterval(DM.timer); DM.timer=null; }
    var b=document.getElementById('dm-start'); b.disabled=false; b.textContent='Start Challenge';
    DM.challenge=null;
  } else dmLose(note);
});

/* live RGC trace */
var dmCanvas=document.getElementById('dm-canvas'), dmCtx=dmCanvas.getContext('2d');
var DMH=76, DMW=400;
function dmResize(){
  var w=dmCanvas.parentNode.clientWidth; if(w<200) w=200;
  DMW=w; var d=Math.min(window.devicePixelRatio||1,2);
  dmCanvas.width=Math.round(DMW*d); dmCanvas.height=Math.round(DMH*d);
  dmCanvas.style.height=DMH+'px';
  dmCtx.setTransform(d,0,0,d,0,0);
}
window.addEventListener('resize',dmResize);
function dmDraw(){
  var M2=DM.model, L=48, w=DMW-L-10, y=DMH/2+4;
  dmCtx.clearRect(0,0,DMW,DMH);
  dmCtx.font=FONT; dmCtx.textBaseline='middle'; dmCtx.textAlign='right';
  dmCtx.fillStyle='#555'; dmCtx.fillText('RGC 1', L-5, y);
  dmCtx.strokeStyle=COL.gray; dmCtx.lineWidth=2;
  dmCtx.beginPath(); dmCtx.moveTo(L,y); dmCtx.lineTo(L+w,y); dmCtx.stroke();
  if(DM.challenge){
    dmCtx.strokeStyle=COL.green; dmCtx.lineWidth=6;
    dmCtx.beginPath();
    var run=false;
    for(var i=0;i<NBUF;i++){
      var sp=M2.spike[0][(M2.head+1+i)%NBUF], x=L+(i/(NBUF-1))*w;
      if(sp&&!run){ dmCtx.moveTo(x,y); run=true; } else if(sp){ dmCtx.lineTo(x,y); } else run=false;
    }
    dmCtx.stroke();
  }
  dmCtx.strokeStyle='#999'; dmCtx.lineWidth=1;
  dmCtx.beginPath(); dmCtx.moveTo(L,DMH-12.5); dmCtx.lineTo(L+w,DMH-12.5); dmCtx.stroke();
  dmCtx.textAlign='center'; dmCtx.fillStyle='#555';
  dmCtx.fillText('10 s', L+w/2, DMH-5);
}

cbBuildMenu(); cbLoad(Object.keys(CB_DATA)[0]);
dmBuildMenu(); dmSyncDots(); dmResize();

/* ---------- boot + host API ---------- */
function readHash(){
  var q={};
  (location.hash||'').replace(/^#/,'').split('&').forEach(function(kv){
    var p=kv.split('='); if(p[0]) q[decodeURIComponent(p[0])]=decodeURIComponent(p[1]||'');
  });
  return q;
}
resize();
var q=readHash();
if(q.preset && loadPreset(q.preset)){
  /* deep-linked figures keep running unless told otherwise */
  if(q.running==='0'){ M.running=false; armStimulus(M); syncStim(); }
} else {
  /* Clean start, matching DataManager.__init__: nothing wired, nothing
     selected, stimulus off. The reader builds the first circuit themselves. */
  M.running=false; M.mode='Static'; M.selected=grid(false);
  armStimulus(M); clearTraces(M); syncAll();
}
requestAnimationFrame(frame);

/* ============================================================================
   TUTORIALS — guided tours that play on the widget itself
   ---------------------------------------------------------------------------
   A tour is a list of narration clips ("segments"). Each segment has its text,
   its audio (an mp3 data: URI), its length in seconds, and a list of actions:
       [at, verb, ...arguments]
   `at` is when the action lands:
       1.5      seconds after the clip starts (negative = in the pause before)
       "e+0.5"  half a second after the clip ends
       ">0.4"   0.4 s after the previous action has finished
   The next segment starts once the clip (plus its `post` pause) is over and
   every action has finished, so a tour never talks over its own clicks.
   The actions press the widget's real controls (the same click, change and
   input events a reader would produce), so nothing is faked: what the tour
   builds is a working circuit that the reader keeps when the tour ends.

   Verbs
     spot   t1 t2 ...          dim everything except these targets (none = clear)
     click  target [times]     move the pointer there and click
     point  target             move the pointer there
     leds   "x..x..x.."        select exactly these LEDs (x = selected)
     run    true|false         switch the stimulus on or off
     mode   Static|Motion      dir Left|Right      speed 0|1|2
     wire   rgc "ei......."    set the nine connections (e, i or .)
     delay  rgc {ch:"short"|"medium"|"long"|"None", ...}   via the Delays dialog
     thr    rgc n              pol rgc ON|OFF
     preset "name"             choose from the circuit menu and press Load
     tab    lab|cb|dm|lp|sl    pick  target value   (any <select>)
     value  target n           (any number input)
     dmleds "x........"        Discovery Mode stimulus grid
     dmwire "ei......."        Discovery Mode connections
     cbfill                    fill in every remaining Code Breaker letter
   Targets are short names resolved by tourEl() below, or "css:<selector>".
   ========================================================================== */
var TOURS = [{"id":"use","title":"How to use RetINaBox","segs":[{"text":"Welcome to RetINaBox: a retina in a box. Light up model photoreceptors, wire them to two ganglion cells, and watch how the circuit responds.","acts":[[2.9,"spot","panel:1"],[4.9,"spot","panel:2"],[6.9,"spot","panel:3"]],"post":0.3,"dur":8.784,"audio":"data:audio/mpeg;base64,"},{"text":"On the left is the Visual Stimulus Controller. Its nine LEDs are the light stimulus, one for each photoreceptor.","acts":[[-0.3,"spot","panel:1"]],"post":0.2,"dur":7.008,"audio":"data:audio/mpeg;base64,"},{"text":"Click an LED to select it, then press Activate stimulus LEDs to switch it on. Press again to switch it off.","acts":[[1.0,"click","lamp:5"],[3.5,"click","run"],[5.9,"click","run"]],"pre":0.2,"post":0.3,"dur":6.744,"audio":"data:audio/mpeg;base64,"},{"text":"In Motion mode, the pattern sweeps left or right across the grid, at a speed you choose.","acts":[[0.7,"mode","Motion"],[">0.3","run",true],[2.7,"dir","Left"],[4.0,"point","speed"],["e+0.8","run",false],[">0.3","mode","Static"]],"pre":0.4,"dur":4.992,"audio":"data:audio/mpeg;base64,"},{"text":"In the middle is the Connectivity Manager, where you wire the photoreceptors to two ganglion cells: RGC 1 and RGC 2.","acts":[[-0.3,"spot","panel:2"],[5.3,"spot","rgc:1"],[6.5,"spot","rgc:2"],["e+0.2","spot","panel:2","panel:3"]],"pre":0.4,"post":0.3,"dur":7.872,"audio":"data:audio/mpeg;base64,"},{"text":"Click a connection to cycle it: silent, excitatory in red, or inhibitory in blue.","acts":[[0.5,"point","dot:1:5"],[2.9,"click","dot:1:5"],[4.1,"click","dot:1:5"],["e+0.5","wire",1,"....e...."]],"post":0.4,"dur":5.136,"audio":"data:audio/mpeg;base64,"},{"text":"Threshold is how many excitatory inputs, minus inhibitory ones, the cell needs before it fires.","acts":[[0.3,"point","thr:1"],[2.4,"thr",1,2],["e+0.5","thr",1,1]],"pre":0.2,"dur":5.88,"audio":"data:audio/mpeg;base64,"},{"text":"The Delays button slows down individual connections.","acts":[[0.4,"delay",1,{"5":"medium"}]],"post":0.3,"dur":3.24,"audio":"data:audio/mpeg;base64,"},{"text":"And Type sets whether the cell responds when the light turns on, or when it turns off.","acts":[[0.3,"point","pol:1:ON"],[3.2,"click","pol:1:OFF"],["e+0.9","click","pol:1:ON"],[">0.4","mode","Motion"],[">0.3","run",true]],"pre":0.2,"post":0.2,"dur":4.392,"audio":"data:audio/mpeg;base64,"},{"text":"On the right, the Signal Monitor is your recording rig. Circles show which photoreceptors are lit, the traces show what each connection passes on, and the bottom trace is the ganglion cell's output.","acts":[[-0.1,"spot","panel:3"],[3.9,"spot","mon:1:lamps"],[6.0,"spot","mon:1:traces"],[8.4,"spot","mon:1:out"],["e+0.3","spot"]],"pre":0.5,"post":0.4,"dur":11.472,"audio":"data:audio/mpeg;base64,"},{"text":"Want a head start? Choose a ready-made circuit from the menu, such as a pair of direction-selective cells, and press Load a circuit.","acts":[[-0.3,"spot","load","preset"],[2.3,"preset","Direction-selective pair (left and right)"],[">0.7","spot"]],"pre":0.4,"post":1.2,"dur":7.248,"audio":"data:audio/mpeg;base64,"},{"text":"The Code Breaker and Discovery Mode tabs hold challenges, next to the lesson plans and teaching slides.","acts":[[-0.3,"spot","tab:cb","tab:dm","tab:lp","tab:sl"],["e+0.5","spot"]],"post":0.6,"dur":5.928,"audio":"data:audio/mpeg;base64,"}]},{"id":"centre-surround","title":"Centre-surround receptive fields","segs":[{"text":"Let's build a receptive field. Start simple: connect photoreceptor five to ganglion cell one, with one excitatory connection.","acts":[[3.6,"wire",1,"....e...."]],"dur":7.632,"audio":"data:audio/mpeg;base64,"},{"text":"Shine light on photoreceptor five, and the cell fires. Move the light anywhere else, and the cell stays silent.","acts":[[0.5,"leds","....x...."],[">0.4","run",true],[4.3,"leds","x........"]],"post":1.4,"dur":6.144,"audio":"data:audio/mpeg;base64,"},{"text":"Now connect a different photoreceptor, number three, to ganglion cell two.","acts":[[2.2,"wire",2,"..e......"]],"dur":3.96,"audio":"data:audio/mpeg;base64,"},{"text":"A small spot of light activates only the cell it sits over, so together the two cells signal where the light is.","acts":[[0.4,"leds","..x......"],[3.4,"leds","....x...."]],"post":1.2,"dur":6.12,"audio":"data:audio/mpeg;base64,"},{"text":"But switch on every LED, and both cells fire. Cells like these can't tell a small spot from a flood of light.","acts":[[1.2,"click","all"]],"post":0.6,"dur":6.264,"audio":"data:audio/mpeg;base64,"},{"text":"The fix is an inhibitory surround. In each cell, make all the other connections inhibitory.","acts":[[2.6,"wire",1,"iiiieiiii"],[">0.5","wire",2,"iieiiiiii"]],"post":0.6,"dur":5.208,"audio":"data:audio/mpeg;base64,"},{"text":"Now uniform light cancels itself out, and both cells fall silent. But a small spot over a cell's centre still drives it.","acts":[[4.4,"click","none"],[">0.4","leds","....x...."],[">2.0","leds","..x......"]],"post":1.6,"dur":7.32,"audio":"data:audio/mpeg;base64,"},{"text":"Centre-surround cells respond to local contrast, not overall brightness. They are tuned to the size of a stimulus, its spatial frequency, and carry more useful information about space.","acts":[],"post":0.5,"dur":10.92,"audio":"data:audio/mpeg;base64,"},{"text":"The same recipe can tune cells to different sizes. Keep cell one as a small-spot detector. Give cell two a bigger centre around the same photoreceptor: a plus shape of five excitatory inputs, with a threshold of five.","acts":[[0.5,"leds","....x...."],[6.4,"wire",2,"ieieeeiei"],[">0.5","thr",2,5]],"post":0.8,"dur":13.416,"audio":"data:audio/mpeg;base64,"},{"text":"A small spot drives only cell one. A bigger spot drives only cell two, because in cell one the surround now cancels the centre.","acts":[[2.9,"leds",".x.xxx.x."]],"post":2.0,"dur":7.68,"audio":"data:audio/mpeg;base64,"}]},{"id":"orientation","title":"Orientation selectivity and shape","segs":[{"text":"Many visual neurons prefer lines of one orientation. Let's build one. Give ganglion cell one excitatory connections from the middle column, inhibitory connections from the other six photoreceptors, and a threshold of three.","acts":[[5.0,"wire",1,"ieiieiiei"],[">0.5","thr",1,3]],"dur":13.44,"audio":"data:audio/mpeg;base64,"},{"text":"A vertical line through the middle drives the cell.","acts":[[0.2,"leds",".x..x..x."],[">0.4","run",true]],"post":1.6,"dur":2.688,"audio":"data:audio/mpeg;base64,"},{"text":"A horizontal line does not: it covers one excitatory input and two inhibitory ones.","acts":[[0.3,"leds","...xxx..."]],"post":1.0,"dur":5.304,"audio":"data:audio/mpeg;base64,"},{"text":"Now make ganglion cell two prefer horizontal lines: middle row excitatory, the rest inhibitory, threshold three.","acts":[[2.6,"wire",2,"iiieeeiii"],[">0.5","thr",2,3]],"post":1.0,"dur":6.864,"audio":"data:audio/mpeg;base64,"},{"text":"Each cell now signals its own orientation.","acts":[[1.0,"leds",".x..x..x."]],"post":2.0,"dur":2.688,"audio":"data:audio/mpeg;base64,"},{"text":"Next, a shape detector. A plus sign is a vertical and a horizontal line together. But show these cells a plus, and both stay silent, because each line falls on the other cell's inhibitory inputs.","acts":[[5.6,"leds",".x.xxx.x."]],"post":0.8,"dur":11.376,"audio":"data:audio/mpeg;base64,"},{"text":"So in each cell, silence the two inputs that lie on the other cell's line.","acts":[[1.6,"wire",1,"iei.e.iei"],[">0.5","wire",2,"i.ieeei.i"]],"post":0.8,"dur":3.96,"audio":"data:audio/mpeg;base64,"},{"text":"Now the plus drives both cells at once, while a single line still drives only one.","acts":[[2.9,"leds",".x..x..x."],[">1.8","leds",".x.xxx.x."]],"post":1.2,"dur":4.776,"audio":"data:audio/mpeg;base64,"},{"text":"A downstream neuron that fires only when both cells are active would be a plus detector. In the real visual system, selectivity like this is built in visual cortex, so think of these two as model cortical neurons.","acts":[],"post":0.8,"dur":12.888,"audio":"data:audio/mpeg;base64,"}]},{"id":"direction","title":"Direction selectivity","segs":[{"text":"A direction-selective cell fires for motion in one direction, but not the other. There are two classic ways to build one. Our stimulus is a spot of light moving along the middle row.","acts":[[6.6,"leds","...x....."],[">0.4","mode","Motion"],[">0.4","run",true]],"post":0.6,"dur":10.32,"audio":"data:audio/mpeg;base64,"},{"text":"First, the Reichardt detector. Connect photoreceptors four and five with excitation, set the threshold to two, and delay the signal from four.","acts":[[2.4,"wire",1,"...ee...."],[">0.5","thr",1,2],[">0.5","delay",1,{"4":"medium"}]],"post":1.0,"dur":8.376,"audio":"data:audio/mpeg;base64,"},{"text":"When the spot moves right, the delayed signal from four arrives together with the signal from five, and the cell fires. Moving left, they never coincide, and the cell is silent.","acts":[["e-3.6","dir","Left"]],"post":2.0,"dur":10.416,"audio":"data:audio/mpeg;base64,"},{"text":"Second, the Barlow–Levick model. In ganglion cell two, photoreceptor five excites, and photoreceptor six sends delayed inhibition.","acts":[[3.0,"wire",2,"....ei..."],[">0.5","delay",2,{"6":"medium"}]],"post":0.8,"dur":7.92,"audio":"data:audio/mpeg;base64,"},{"text":"Moving left, the spot reaches six first, so the inhibition arrives just in time to cancel the excitation. Moving right, the excitation gets there first, and the cell fires.","acts":[["e-3.8","dir","Right"]],"post":2.0,"dur":10.464,"audio":"data:audio/mpeg;base64,"},{"text":"For a really robust detector, combine the two: in cell one, add delayed inhibition from photoreceptor six.","acts":[[3.4,"wire",1,"...eei..."],[">0.5","delay",1,{"6":"medium"}]],"post":0.6,"dur":6.456,"audio":"data:audio/mpeg;base64,"},{"text":"Then make cell two the mirror image, so that it prefers leftward motion.","acts":[[1.2,"wire",2,"...iee..."],[">0.5","thr",2,2],[">0.5","delay",2,{"4":"medium","6":"medium"}]],"post":1.4,"dur":3.96,"audio":"data:audio/mpeg;base64,"},{"text":"Rightward motion drives cell one. Leftward motion drives cell two.","acts":[[2.2,"dir","Left"]],"post":2.4,"dur":4.152,"audio":"data:audio/mpeg;base64,"},{"text":"Last, speed. The delay sets the speed a cell prefers. Give both cells the same preferred direction, but long delays in cell one and short delays in cell two.","acts":[[4.4,"wire",2,"...eei..."],[">0.5","delay",2,{"4":"short","6":"short"}],[">0.5","delay",1,{"4":"long","6":"long"}],[">0.5","dir","Right"]],"post":0.5,"dur":9.36,"audio":"data:audio/mpeg;base64,"},{"text":"Slow motion drives cell one, while cell two gives only brief blips. Fast motion drives cell two, and cell one falls silent.","acts":[[0.2,"speed",0],["e-3.0","speed",2]],"pre":0.5,"post":3.0,"dur":7.752,"audio":"data:audio/mpeg;base64,"}]},{"id":"code-breaker","title":"How Code Breaker works","end":"End of the tutorial. Choose a challenge and decode it yourself.","segs":[{"text":"In Code Breaker, a secret message is written as a series of light patterns, and you decode it with RetINaBox.","acts":[[-0.7,"tab","cb"],[1.6,"spot","css:#rb-mode-cb .rb-box"]],"pre":1.0,"dur":6.48,"audio":"data:audio/mpeg;base64,"},{"text":"Each challenge gives you the preferred stimulus of each ganglion cell, and a cipher that turns the two cells' responses into a letter.","acts":[[0.6,"spot","cb-pref"],[4.0,"spot","css:.rb-book"],["e+0.4","spot"]],"dur":7.2,"audio":"data:audio/mpeg;base64,"},{"text":"First, build the decoder in the Lab. Ganglion cell one should fire only for its preferred pattern: excitatory connections from those four photoreceptors, and a threshold of four.","acts":[[1.4,"tab","lab"],[6.4,"wire",1,".ee.ee..."],[">0.5","thr",1,4]],"post":0.4,"dur":10.488,"audio":"data:audio/mpeg;base64,"},{"text":"Cell two prefers a single spot, at position seven.","acts":[[0.8,"wire",2,"......e.."]],"post":0.4,"dur":3.048,"audio":"data:audio/mpeg;base64,"},{"text":"Make the remaining inputs inhibitory, but leave silent any input that belongs to the other cell's pattern, so that both cells can fire together.","acts":[[0.6,"wire",1,"ieeiee.ii"],[">0.5","wire",2,"i..i..eii"]],"post":0.5,"dur":8.16,"audio":"data:audio/mpeg;base64,"},{"text":"Now show the circuit each pattern in the message, starting with the first.","acts":[[0.3,"tab","cb"],[">0.3","spot","tile:1"],["e+0.9","spot"],[">0.2","tab","lab"],[">0.5","leds","......x.."],[">0.4","run",true]],"post":1.5,"dur":4.032,"audio":"data:audio/mpeg;base64,"},{"text":"Only cell two fires. In the cipher, zero, one, is the letter D.","acts":[[1.6,"tab","cb"],[">0.3","spot","css:#cb-book tr:nth-child(3)"],["e+0.5","spot","tile:1"],[">0.4","pick","tilesel:1","D"],[">0.8","spot"]],"post":0.3,"dur":4.056,"audio":"data:audio/mpeg;base64,"},{"text":"The third pattern drives both cells: one, one, which is the letter A.","acts":[[0.2,"spot","tile:3"],[1.5,"spot"],[">0.2","tab","lab"],[">0.5","leds",".xx.xxx.."],["e+1.6","tab","cb"],[">0.3","spot","css:#cb-book tr:nth-child(4)"],[">1.3","spot","tile:3"],[">0.4","pick","tilesel:3","A"],[">0.8","spot"]],"post":0.3,"dur":4.08,"audio":"data:audio/mpeg;base64,"},{"text":"Work through every pattern in the same way, then press Check Answers.","acts":[[1.0,"cbfill"],[">0.6","click","cb-check"],[">0.4","spot","cb-result"]],"post":1.2,"dur":3.504,"audio":"data:audio/mpeg;base64,"},{"text":"All correct. Every challenge has different receptive fields, a different cipher, and a new message to crack.","acts":[["e+0.3","spot"]],"post":0.8,"dur":5.904,"audio":"data:audio/mpeg;base64,"}]},{"id":"discovery","title":"How Discovery Mode works","end":"End of the tutorial. Choose a challenge and press Start Challenge.","segs":[{"text":"Discovery Mode turns the problem around. A mystery ganglion cell is hidden in the box, and you work out what it responds to, and how it is wired, the way a neuroscientist would.","acts":[[-0.7,"tab","dm"]],"pre":1.0,"dur":10.104,"audio":"data:audio/mpeg;base64,"},{"text":"Choose a challenge and press Start. You begin with one hundred points, and every wrong answer costs five.","acts":[[1.7,"click","dm-start"],[3.2,"spot","css:.rb-dmbar"],["e+0.4","spot"]],"dur":5.544,"audio":"data:audio/mpeg;base64,"},{"text":"Phase one: find the cell's preferred stimulus. Try a pattern of light, and watch the live response.","acts":[[0.2,"spot","dm-p1"],[3.6,"spot","dm-p1","css:.rb-dmtop .rb-box:nth-child(2)"],[4.0,"dmleds","....x...."]],"post":1.2,"dur":5.472,"audio":"data:audio/mpeg;base64,"},{"text":"Nothing. And if you test a wrong guess, you lose points.","acts":[[1.6,"click","dm-t1"],[">0.4","spot","css:.rb-dmbar","dm-p1"]],"post":1.2,"dur":2.832,"audio":"data:audio/mpeg;base64,"},{"text":"So explore before you test. Light on position four makes the cell fire.","acts":[[-0.1,"spot","dm-p1","css:.rb-dmtop .rb-box:nth-child(2)"],[2.0,"dmleds","...x....."]],"post":1.6,"dur":4.392,"audio":"data:audio/mpeg;base64,"},{"text":"Add position five as well, and the cell stops: so five must be inhibitory.","acts":[[0.5,"dmleds","...xx...."],["e+0.8","dmleds","...x....."]],"post":0.6,"dur":4.608,"audio":"data:audio/mpeg;base64,"},{"text":"Position four alone is the preferred stimulus. Test it, and phase two unlocks.","acts":[[2.8,"click","dm-t1"],[">0.6","spot","dm-p2"]],"post":0.6,"dur":4.656,"audio":"data:audio/mpeg;base64,"},{"text":"Phase two: reconstruct the circuit. Position four excites the cell. Testing the other positions one at a time shows that each of them silences it, so they are all inhibitory.","acts":[[3.4,"dmwire","...e....."],[8.0,"dmwire","iiieiiiii"]],"post":0.4,"dur":10.008,"audio":"data:audio/mpeg;base64,"},{"text":"With the threshold at one, and the cell type set to ON, test your connectivity.","acts":[[0.4,"point","dm-thr"],[2.0,"point","css:input[name=\"dm-pol\"][value=\"ON\"]"],["e+0.2","click","dm-t2"],[">0.8","spot"]],"post":1.0,"dur":4.2,"audio":"data:audio/mpeg;base64,"},{"text":"Challenge completed. Harder challenges hide bigger receptive fields and moving stimuli, where you also work out speed, direction and delays.","acts":[],"post":0.8,"dur":8.328,"audio":"data:audio/mpeg;base64,"}]}];

var tourSel = document.getElementById('rb-tour-sel'), tourGo = document.getElementById('rb-tour-go');
