/* ---------- targets ---------- */
function tourEl(name) {
  var p = String(name).split(':'), k;
  switch (p[0]) {
    case 'lamp':   return elLamps.children[+p[1] - 1];
    case 'run':    return elRun;
    case 'all':    return document.getElementById('rb-all');
    case 'none':   return document.getElementById('rb-none');
    case 'mode':   return root.querySelector('input[name="rb-mode"][value="' + p[1] + '"]');
    case 'dir':    return root.querySelector('input[name="rb-dir"][value="' + p[1] + '"]');
    case 'speed':  return document.getElementById('rb-speed');
    case 'dot':    return dotEls[+p[1] - 1][+p[2] - 1];
    case 'thr':    return document.getElementById('rb-thr-' + (+p[1] - 1));
    case 'delays': return document.getElementById('rb-delays-' + (+p[1] - 1));
    case 'pol':    return root.querySelector('input[name="rb-pol-' + (+p[1] - 1) + '"][value="' + p[2] + '"]');
    case 'panel':  return root.querySelectorAll('#rb-mode-lab .rb-panel')[+p[1] - 1];
    case 'rgc':    return document.getElementById('rb-neurons').children[+p[1] - 1];
    case 'neuron': return root.querySelectorAll('#rb-neurons .rb-neuron')[+p[1] - 1];
    case 'tab':    return root.querySelector('.rb-tab[data-mode="' + p[1] + '"]');
    case 'load':   return document.getElementById('rb-load');
    case 'preset': return document.getElementById('rb-preset');
    case 'sheet':  return root.querySelector('#rb-modal .rb-sheet');
    case 'unit':   return document.getElementById('rb-units').children[+p[1] - 1];
    case 'slider': k = document.getElementById('rb-units').children[+p[1] - 1]; return k && k.querySelector('input');
    case 'done':   return document.getElementById('rb-modal-x');
    case 'menu':   return tourMenu && [].filter.call(tourMenu.children, function (d) { return d.textContent === p.slice(1).join(':'); })[0];
    case 'tile':   return root.querySelectorAll('#cb-code .rb-tok[data-answer]')[+p[1] - 1];
    case 'tilesel':k = root.querySelectorAll('#cb-code .rb-tok[data-answer]')[+p[1] - 1]; return k && k.querySelector('select');
    case 'dmcell': return document.getElementById('dm-grid').children[+p[1] - 1];
    case 'dmdot':  return document.getElementById('dm-dots').children[+p[1] - 1];
    case 'css':    return root.querySelector(p.slice(1).join(':'));
