/* rectangle of a target in page coordinates; "mon:" targets are regions of the Signal Monitor drawing */
function tourRect(name) {
  var p = String(name).split(':');
  if (p[0] === 'mon') {
    var c = canvas.getBoundingClientRect(), k = +p[1] - 1, top = PAD + k * BLOCK, plot = top + TITLE, w = CW - LEFT - RIGHT;
    var sx = c.width / CW, sy = c.height / CH, r;
    if (!c.width) return null;
