  function click(to, n, gap) { out.push({ to: to, gap: gap, fn: function () { var e = tourEl(to); if (e) tourPress(e, n); } }); }
  function cycles(now, want) {
    var w = want === 'e' ? 'excitatory' : want === 'i' ? 'inhibitory' : 'off';
    return (STATES.indexOf(w) - STATES.indexOf(now) + 3) % 3;
  }
  if (verb === 'click') click(a[2], a[3]);
  else if (verb === 'tab') { if (currentMode !== a[2]) click('tab:' + a[2]); }
  else if (verb === 'run') { if (M.running !== !!a[2]) click('run'); }
  else if (verb === 'mode') { if (M.mode !== a[2]) click('mode:' + a[2]); }
  else if (verb === 'dir') { if (M.direction !== a[2]) click('dir:' + a[2]); }
