    if (wantOn === 9 && on < 9) click('all');
    else {
      for (i = 0; i < 9; i++) if (a[2].charAt(i) === 'x' && !M.selected[(i / 3) | 0][i % 3]) click('lamp:' + (i + 1));
      for (i = 0; i < 9; i++) if (a[2].charAt(i) !== 'x' && M.selected[(i / 3) | 0][i % 3]) click('lamp:' + (i + 1));
