    k = a[2] - 1; var todo = [];
    for (ch = 1; ch <= 9; ch++) if (a[3][ch] != null && M.rgc[k].conn[((ch - 1) / 3) | 0][(ch - 1) % 3].delay !== a[3][ch]) todo.push(ch);
