  for (var k = 0; k < 2; k++) M.rgc[k] = { polarity: 'ON', threshold: 1, conn: blankConn() };
  armStimulus(M); clearTraces(M); syncAll();
  var cbS = document.getElementById('cb-sel'); if (cbS.options.length) { cbS.selectedIndex = 0; tourFire(cbS, 'change'); }
  if (dmSel.options.length) { dmSel.selectedIndex = 0; tourFire(dmSel, 'change'); }
