    '<path fill="rgba(20,20,20,.5)" fill-rule="evenodd"/><g fill="none" stroke="#00D9B8" stroke-width="3"/></svg>' +
    '<div id="rb-tour-menu" hidden></div><div id="rb-tour-rip"></div>' +
    '<svg id="rb-tour-cur" viewBox="0 0 24 24"><path d="M3 2l0 17 4.6-4.2 3 6.7 2.9-1.3-3-6.6 6.3-.4z" fill="#111" stroke="#fff" stroke-width="1.4" stroke-linejoin="round"/></svg>';
  root.appendChild(tourLayer);
  tourDim = tourLayer.querySelector('#rb-tour-spot path'); tourOut = tourLayer.querySelector('#rb-tour-spot g');
  tourCur = tourLayer.querySelector('#rb-tour-cur'); tourRip = tourLayer.querySelector('#rb-tour-rip');
  tourMenu = tourLayer.querySelector('#rb-tour-menu');
}
function tourStart(id) {
  var def = null; TOURS.forEach(function (t) { if (t.id === id) def = t; });
  if (!def) return false;
  tourStop(true);
  tourResetAll(); tourBuildLayer();
  if (!tourAudio) tourAudio = new Audio();
  var o = root.getBoundingClientRect();
  tour = { def: def, seg: -1, st: 0, q: [], busy: 0, said: false, last: 0, paused: false, done: false,
           cx: o.width * 0.5, cy: Math.min(o.height - 30, 380), move: null, rip: -1e9, clock: 0,
           spot: [], next: null, under: null, alpha: 0 };
  tourSel.value = id;
