}
function tourPin() {                     /* pin the caption to the window once the header has scrolled away */
  root.classList.toggle('rb-tourpin', !tourBar.hidden && tourHead.getBoundingClientRect().top < -1);
}
window.addEventListener('scroll', tourPin, { passive: true });
window.addEventListener('resize', tourPin);
function tourShow() {                    /* the caption takes the place of the logo and title: no extra height */
  root.classList.add('rb-touring'); root.classList.add('rb-tourshow'); tourLayer.hidden = false; tourMenu.hidden = true;
  tourBar.hidden = false; tourBar.classList.remove('is-done');
  tourPauseBtn.textContent = 'Pause'; tourPauseBtn.hidden = tourMuteBtn.hidden = tourNextBtn.hidden = false;
  tourPin();
}
function tourStop(keepBar) {
  cancelAnimationFrame(tourRaf);
  if (tourAudio) { try { tourAudio.pause(); } catch (e) {} }
  if (tourMenu) tourMenu.hidden = true;
  if (tourLayer) tourLayer.hidden = true;
  root.classList.remove('rb-touring');
  if (tour && !modal.hidden && !tour.done) modal.hidden = true;
  tour = null;
  if (!keepBar) { tourBar.hidden = true; root.classList.remove('rb-tourshow'); root.classList.remove('rb-tourpin'); }
}
function tourPause(p) {
  if (!tour || tour.done) return;
  tour.paused = p; tourPauseBtn.textContent = p ? 'Resume' : 'Pause';
  try {
    if (p) tourAudio.pause();
    else if (tour.said && !tourAudio.ended && tour.st < tour.def.segs[tour.seg].dur) { var pr = tourAudio.play(); if (pr && pr.catch) pr.catch(function () {}); }
