function tourFinish() {                  /* hand the widget back, keep what was built */
  tour.done = true; tourLayer.hidden = true; root.classList.remove('rb-touring');
  tourCap.textContent = tour.def.end || 'End of the tutorial. The circuit is yours: change it and see what happens.';
  tourCount.textContent = tour.def.segs.length + ' / ' + tour.def.segs.length;
  tourFire2.classList.remove('is-lab'); tourBar.classList.add('is-done'); tourPauseBtn.hidden = tourMuteBtn.hidden = tourNextBtn.hidden = true; tourProg.style.width = '100%';
}
/* ---------- back / next: jump to the start of any section ----------
   The widget is reset and every action of the earlier sections is replayed at once, with the same code
   that presses the controls during normal play, so the circuit is exactly what it would have been. */
function tourApply(i) {
  tourResetAll(); tourMenu.hidden = true;
  tour.spot = []; tour.next = null; tour.under = null; tour.move = null; tour.alpha = 0;
  for (var j = 0; j < i; j++) (tour.def.segs[j].acts || []).forEach(function (a) {
