tourGo.addEventListener('click', function () { tourStart(tourSel.value); });
tourPauseBtn.addEventListener('click', function () { if (tour) tourPause(!tour.paused); });
tourMuteBtn.addEventListener('click', function () {
  tourMuted = !tourMuted; if (tourAudio) tourAudio.muted = tourMuted;
  tourMuteBtn.textContent = tourMuted ? 'Sound on' : 'Mute';
});
tourBackBtn.addEventListener('click', function () {   /* early in a section: previous section; otherwise replay this one */
  if (!tour) return;
  tourJump(tour.done ? tour.def.segs.length - 1 : tour.st > 2.5 ? tour.seg : tour.seg - 1);
});
tourNextBtn.addEventListener('click', function () { if (tour && !tour.done) tourJump(tour.seg + 1); });
document.getElementById('rb-tour-again').addEventListener('click', function () { tourStart(tourSel.value); });
document.getElementById('rb-tour-end').addEventListener('click', function () { tourStop(false); });

window.RetINaBox={
  presets:PRESETS.map(function(p){return {id:p.id,name:p.name};}),
  load:loadPreset,
  start:function(){ M.running=true;  armStimulus(M); syncStim(); },
  stop: function(){ M.running=false; armStimulus(M); syncStim(); },
  reset:function(){ clearTraces(M); },
  /* Drop in the desktop app's real challenge files:
     RetINaBox.loadChallenges({codeBreaker: <json>, discoveryMode: <json>}) */
  loadChallenges:function(o){
    if(o && o.codeBreaker){ CB_DATA=o.codeBreaker; cbBuildMenu(); cbLoad(Object.keys(CB_DATA)[0]); }
    if(o && o.discoveryMode){ DM_DATA=o.discoveryMode; dmBuildMenu(); dmSel.dispatchEvent(new Event('change')); }
  },
  /* Point the viewers elsewhere, e.g. copies hosted on theopenbrain.org:
     RetINaBox.setDocs({lp:{url:'/docs/lessons.pdf'}, sl:{url:'/docs/slides.pdf'}}) */
  setDocs:function(o){
    ['lp','sl'].forEach(function(k){
      if(o && o[k]){
        if(o[k].url) DOCS[k].url = o[k].url;
        if(o[k].gh_url) DOCS[k].gh_url = o[k].gh_url;
        var b=document.getElementById(DOCS[k].frame);
        /* rebuild the loading overlay too, or an overridden doc loses it */
        b.innerHTML='<p class="note">Loading\u2026</p>';
        delete b.dataset.mounted;
        if(currentMode===k) mountDoc(k);
      }
    });
  },
  showTab:function(m){ var t=document.querySelector('.rb-tab[data-mode="'+m+'"]'); if(t) t.click(); },
  getState:function(){
    return JSON.parse(JSON.stringify({selected:M.selected,mode:M.mode,speed:M.speed,
      direction:M.direction,running:M.running,rgc:M.rgc}));
  },
  setState:function(s){
    if(!s) return;
    ['selected','mode','speed','direction','running'].forEach(function(kk){
      if(kk in s) M[kk]=JSON.parse(JSON.stringify(s[kk]));
    });
    if(s.rgc) M.rgc=JSON.parse(JSON.stringify(s.rgc));
    armStimulus(M); clearTraces(M); syncAll();
  },
  /* fraction of the last `sec` seconds that each cell spent firing: [RGC1, RGC2, Discovery Mode cell] */
  firing:function(sec){
    var n=Math.max(1,Math.min(NBUF,Math.round((sec||1)*1000/DT_MS)));
    return [[M,0],[M,1],[DM.model,0]].map(function(p){
      for(var i=0,c=0;i<n;i++) c+=p[0].spike[p[1]][(p[0].head-i+NBUF)%NBUF];
      return c/n; });
  },
  /* Tutorials: RetINaBox.tour.list, .start(id), .stop(), .pause(true|false), .go(section), .state() */
  tour:{
    list:TOURS.map(function(t){ return {id:t.id, title:t.title}; }),
    start:tourStart,
    stop:function(){ tourStop(false); },
    pause:tourPause,
    go:tourJump,
    state:function(){ return tour ? {id:tour.def.id, segment:tour.seg, time:tour.st, clock:tour.clock,
                                     paused:tour.paused, done:tour.done} : null; }
  }
};
})();
</script>
</body>
</html>
$w$,
  'published')
on conflict (slug) do update
  set title = excluded.title, description = excluded.description, author = excluded.author,
      ramp = excluded.ramp, html = excluded.html, status = excluded.status, updated_at = now();

do $$
declare
  chapter_id uuid;
  m record;
  old_id uuid;
  new_id uuid;
  n integer;
  total integer := 0;
begin
  select id into chapter_id from public.modules where slug = 'the-retina';
  if chapter_id is null then
    raise notice 'Retina widgets: no the-retina module, skipped';
    return;
  end if;

  for m in
    select * from (values
      ('animationPhotoreceptors', 'retina-photoreceptors', 'Photoreceptors', 'pane'),
      ('animationPhototransduction', 'retina-phototransduction', 'Phototransduction', 'band'),
      ('animationTheVisualCycle', 'retina-visual-cycle', 'The visual cycle', 'band'),
      ('animationPupillaryLightreflex', 'retina-pupillary-light-reflex', 'Pathway for the pupillary light reflex', 'band'),
      ('animationImpairedVision', 'retina-refraction-errors', 'Refractive errors', 'band'),
      ('animationOnOff', 'retina-on-off-bipolar-cells', 'ON and OFF bipolar cells', 'pane'),
      ('animationRetinalCellTypes', 'retina-retinal-cell-types', 'Retinal cell types', 'pane'),
      ('animationSynapticArchitecture', 'retina-synaptic-architecture', 'Synaptic architecture', 'pane'),
      ('animationCenterSurroundReceptiveFields', 'retina-center-surround', 'Center-surround receptive fields', 'pane'),
      ('animationDirectionSelectivity', 'retina-direction-selectivity', 'Direction selectivity', 'pane'),
      ('animationObjectMotionSensitivity', 'retina-object-motion-sensitivity', 'Object motion sensitivity', 'pane'),
      ('animationRodVsConeCircuits', 'retina-rod-vs-cone-circuits', 'Rod and cone circuits', 'pane'),
      ('animationLightSensitiveGanglionCells', 'retina-light-sensitive-ganglion-cells', 'Light-sensitive ganglion cells', 'pane')
    ) as t(old_key, slug, title, mode)
  loop
    insert into public.animations
      (animation_key, title, media_type, interaction_type, component_name,
       config, scientific_domain, load_priority)
    values (
      'widget-upload:' || m.slug, m.title,
      'widget', 'click_states', 'IllustrationWidget',
      jsonb_build_object('widgetId', 'upload:' || m.slug, 'credit', 'Stuart Trenholm'),
      'retina', 'low')
    on conflict (animation_key) do update
      set title = excluded.title, media_type = excluded.media_type,
          component_name = excluded.component_name,
          config = excluded.config, updated_at = now()
    returning id into new_id;

    select id into old_id from public.animations where animation_key = m.old_key;
    if old_id is null then
      raise notice 'Retina widgets: no % row, % not placed', m.old_key, m.slug;
      continue;
    end if;

    if m.mode = 'pane' then
      update public.paragraphs p
         set animation_id = new_id, has_animation = true,
             animation_trigger = 'auto', updated_at = now()
        from public.sections s
       where p.section_id = s.id and s.module_id = chapter_id
         and p.animation_id = old_id;
    else
      update public.paragraphs p
         set content = jsonb_build_object('blocks', jsonb_build_array(jsonb_build_object(
               'type', 'widget',
               'widgetId', 'upload:' || m.slug,
               'kind', 'inline',
               'title', m.title,
               'credit', 'Stuart Trenholm'))),
             content_text = m.title,
             animation_id = null, has_animation = false, updated_at = now()
        from public.sections s
       where p.section_id = s.id and s.module_id = chapter_id
         and p.animation_id = old_id
         and p.content -> 'blocks' -> 0 ->> 'type' = 'animation_full';
    end if;
    get diagnostics n = row_count;
    total := total + n;
    raise notice 'Retina widgets: % -> % (%): % paragraph(s)', m.old_key, m.slug, m.mode, n;
  end loop;

  update public.sections
     set title = 'Story of the eye'
   where module_id = chapter_id and title = 'Story of the eye (EDIT)';
  get diagnostics n = row_count;

  raise notice 'Retina widgets: % paragraph(s) re-pointed; "Story of the eye" title fixed (% row)', total, n;
end $$;
